sessions.push(...[{"number":16,"id":"odbNXv9xXjc","url":"https://www.youtube.com/watch?v=odbNXv9xXjc","type":"session","type_he":"סשן","duration":"31:39 דקות","title_he":"לקחים מפיתוח מונחה מפרט","speaker_he":"סימון מרטינלי","summary":"סיימון מרטינלי, יועץ תוכנה שוויצרי בעל 17 שנות ניסיון בפיתוח יישומים עסקיים (ביטוח, סיטונאות, קמעונאות, ממשל), מספר איך מערכת ניהול מתנדבים למועדון אתלטיקה הובילה אותו לפיתוח מונחה-מפרטים. הוא מציג תהליך משלו, AI Unified Process, ומראה בהדגמה חיה איך משחזרים Use Cases מקוד קיים ומייצרים מהם מימוש.","takeaways":["מקרה שימוש מתאר שחקנים, תנאי התחלה, תרחיש הצלחה, זרימות חלופיות ותנאי סיום. מודל הישויות משלים את מבנה התחום; עיצוב ממשק או מפרט API ניתנים בנפרד.","במערכת קיימת מחלצים מקרי שימוש וישויות מקוד, בדיקות ותיעוד, מבקרים עם העסק ורק אז מייצרים מימוש חדש. המטרה היא מודרניזציה של העבודה, לא תרגום מכני בין שפות תכנות.","הוא מעדיף חלוקה אנכית למערכות עצמאיות עם ממשק, לוגיקה ונתונים באותה יחידת הקשר. גם פיזור בין מאות שירותים וגם מונולית ענק מקשים על מסירת הקשר ממוקד.","יוצרים שלד פרויקט בכלים הרשמיים של המסגרת. את הכללים המפורטים מחלקים ל-Skills ולתיעוד נשלף במקום להעמיס קובץ הוראות אחד.","משנים דרישה במפרט ואז מחילים את ההבדל על הקוד הקיים. היקף הביקורת נקבע לפי סיכון עסקי; האצת המימוש מעבירה את צוואר הבקבוק לדרישות ולמפרטים."],"category":"מפרטים ותכנון","coverage":"כל התמליל הזמין נסקר. בטקסט שסופק מופיעים גוף ההרצאה, הסיכום ושאלות מהקהל. אין כאן אימות מול הווידאו או הוכחה שלא חסרו קטעים באמצע.","source_basis":"תמלול מלא שסופק (קובץ מקור 3, פריט 1), כולל פתיחת המנחה, הדגמה ושאלות. תמלול אוטומטי עם שגיאות זיהוי (למשל 'Tesla' במקום Tessl, 'travel' במקום Java). | הושווה לתמלול הרשמי בריפו (talk-martinelli): הרשמי כולל Q3 עד Q5 שחסרו בקובץ שסופק.","lead":"מפרטים לבדם לא מספיקים: תהליך Use Cases + מודל ישויות + Skills שמייצר קוד כמעט דטרמיניסטי","chapters":[{"title":"הסיפור שהתחיל הכול: מערכת מתנדבים ופסטיבל מוזיקה","body":["סיימון פעיל במועדון ספורט (אתלטיקה לילדים, תחרויות כבר 45 שנה) ובונה להם תוכנה מאז 1997. בקיץ 2024 ביקשו ממנו מערכת ניהול מתנדבים חדשה. הוא התחיל לעבוד עם Windsurf בסתיו 2024 וקיבל מערכת עובדת מהר יחסית.","הבעיה הגיעה כשפסטיבל מוזיקה ביקש את אותה מערכת: הוא הבין שאין לו מושג מה בדיוק מומש ואיך לשנות פיצ'רים לפי דרישות חדשות. זה הוביל אותו לפיתוח מונחה-מפרטים. הוא מצא את אתר AI Native (Tessl) ומאמר של סיימון מייפל על פיתוח מונחה AI."],"points":["הטענה: המונח spec-driven ישן (סוף שנות ה-90 / שנות ה-2000), אבל בגרסת ה-AI הוא היה חדש.","הרקע של סיימון: יישומים עסקיים, לא כלים או מוצרים."],"kind":"idea"},{"title":"שתי גישות: כלים מול תהליך","body":["לדבריו יש שני טעמים של spec-driven: גישה סביב כלים (Amazon Kiro, GitHub Spec Kit, שיטת BMAD, וגם כלי Tessl) וגישה סביב תהליך. לדעתו הכלים ממוקדים מדי במפתח יחיד, והוא רוצה לכסות את כל מחזור חיי התוכנה בארגונים גדולים עם תפקידים רבים.","ההבדל המרכזי: בכלים, מסמך דרישות מוביל לתוכנית, התוכנית למשימות, והסוכן מממש משימות. סיימון מדלג על שלב התוכנית והמשימות ומייצר קוד ישירות מ-Use Cases ומודל ישויות."],"points":[],"kind":"idea"},{"title":"AI Unified Process: השלבים","body":["התהליך מתואר בתרשים צבעוני באתר AI Unified Process. בפרויקט חדש מתחילים בחזון ואוספים דרישות (הוא מזכיר שהארגון IREB הוציא מסמך על AI לדרישות הנדסיות, עם מדריך prompting ו-skills).","החלק הירוק הוא המפרט עצמו: System Use Cases ומודל ישויות (קרוב למודל דומיין). בנוסף צריך מידע על ה-UI (למשל עיצוב Figma דרך שרת MCP) או מפרט API. אחר כך נוצרים קוד ובדיקות. הסדר תלוי: ב-UI קשה להתחיל בבדיקות כי קודם צריך לדעת איך המסך נראה; ב-API הוא תמיד יתחיל בבדיקות.","שלב הסקירה תמיד קיים, וכמה סקירה צריך זו שאלה של ניהול סיכונים."],"points":[],"kind":"idea"},{"title":"סיכון קובע כמה סקירה צריך","body":["הוא עובד על מודרניזציה של מערכת ERP לחברת הסיטונאות הגדולה בשוויץ. מודולים שונים בעלי קריטיות שונה: אם ניהול המלאי נופל, העובדים הולכים לשתות קפה; אם ניהול ההזמנות נופל, החברה מפסידה כסף. לכן עומק הסקירה נקבע לפי הסיכון, וזה לא שונה מפיתוח ידני."],"points":[],"kind":"idea"},{"title":"למה דווקא Use Cases ולא User Stories","body":["Use Case בנוי מתנאים מקדימים, תנאים מסיימים, תרחיש הצלחה ראשי ותרחישים חלופיים. הוא טוען ש-AI כבר מכיר את הפורמט כי הוא קיים זמן רב, ושאפשר לראות User Story כזרימה אחת בתוך Use Case. לדעתו Use Cases גדולים יותר ולכן עדיפים.","התנאים המסיימים משמשים כקריטריוני קבלה שאפשר לאמת בבדיקות. הוא משתמש ב-Use Cases כבר מאז עבודתו ברכבת השוויצרית בתחילת שנות ה-2000. הוא אומר שיש לתכנן Use Case אחר Use Case, ושה-spec-driven אינו מפל מים: צריך את אותם שלבים גם בזריז."],"points":[],"kind":"idea"},{"title":"הדגמה: Spring PetClinic משוחזר ל-Use Cases","body":["הוא עשה הנדסה לאחור לאפליקציית הדמו Spring PetClinic (רופאים, בעלים, חיות מחמד, ביקורים). נוצרו דיאגרמת Use Case עם שני שחקנים (מבקר ומשתמש מרפאה) מקובצת למודולים, דיאגרמת ישויות שנגזרת ממודל בסיס הנתונים, והגדרות מפורטות לכל ישות.","לאחר מכן הוא מריץ Claude Code עם הפקודה 'implement' ל-Use Case של רשימת הרופאים. הפרויקטים האלה לא עובדים ב-prompt חופשי: יש Skills לכל דבר והם משתפרים באיטרציות. תוך כ-90 שניות רשימת הרופאים הופיעה במסך. הוא מציין שבדרך כלל לא מריץ בתוך ה-IDE, וזה רק לצורך ההדגמה."],"points":[],"kind":"idea"},{"title":"מעקות בטיחות (Harness): מה גורם לזה לעבוד","body":["התוצאה לדבריו היא פתרון כמעט דטרמיניסטי: אם מוחקים ומריצים שוב מקבלים פחות או יותר אותו הדבר. אבל אדם חייב לסקור לפי רמת הסיכון. הוא מציין שבעיה פתוחה היא הפצת Skills בארגון, כי לא כולם משתמשים באותו סוכן."],"points":["אל תתנו ל-AI ליצור את הפרויקט. השתמשו בכלי הרשמי (למשל Spring Initializr) כדי לקבל תלויות עדכניות ולחסוך טוקנים.","הגדירו כללים, אבל אל תדחסו הכול ל-CLAUDE.md או AGENTS.md. הוא מזכיר מחקר מאוניברסיטת ציריך לפיו System Prompt גדול מגדיל הזיות. לדבריו עדיף אולי בלי קובץ כזה מאשר קובץ גדול.","תיעוד ארכיטקטורה (בפורמט כמו arc42) ושורה בקובץ שמפנה להנחיות.","Skills בשתי רמות: Skills לאפיון, ו-Skills ספציפיים ל-Stack. הוא עובד עם שישה לקוחות ולכל אחד Skills שונים (React + Spring Boot, Vaadin, Angular + Quarkus ועוד).","שרתי MCP עם חיפוש וקטורי בתיעוד גדול, למשל של Frameworks פנימיים, כי Skills לא צריכים להיות גדולים."],"kind":"idea"},{"title":"מודרניזציה: לא lift and shift","body":["רוב עבודתו מודרניזציה של יישומים ארגוניים, כבר כ-8 שנים. הוא מחלץ Use Cases ומודל ישויות מקוד, בדיקות ותיעוד (שמפוזר בכמה מקומות), נותן לאנשי העסק לבדוק אותם, ומייצר קוד חדש.","הוא מבקר את הרעיון של המרת COBOL ל-Java ישירות ('זה לא עבד גם לפני 30 שנה'): מודרניזציה היא חשיבה מחדש על העבודה עם התוכנה. בתחילת הפרויקט ההנחיה הייתה לשכפל את המערכת בדיוק כדי לא להכניס באגים. עכשיו אפשר לשנות את המפרט ולהוסיף פיצ'רים, וגם משתמשי הקצה מרוצים יותר."],"points":[],"kind":"idea"},{"title":"ארכיטקטורה שמתאימה ל-AI: Self-Contained Systems","body":["הוא טוען שהארכיטקטורה משפיעה על איכות העבודה עם AI. מיקרו-שירותים נאיביים (חברת ביטוח עם כ-500 מיקרו-שירותים וכ-500 מיקרו-פרונטאנדים) יוצרים 'כדור בוץ מבוזר' שבו קשה לתת ל-AI הקשר. מונוליט ענק עם אלפי טבלאות הוא גם בעיה כי ההקשר גדול מדי, והוא אומר שהמעבר למודולרי-מונוליט אינו הפתרון.","הפתרון שהוא מציע: Self-Contained Systems, חלוקה לוורטיקלים שבכל אחד UI, לוגיקה עסקית ובסיס נתונים, בדרך כלל במאגר אחד. כך ל-AI יש את כל ההקשר במקום אחד ואפשר לצרף Skills לפי הטכנולוגיה (Vaadin במלאי, React בניהול הזמנות). אם נשארים ב-Stack אחד (Java בלבד או TypeScript בלבד) צריך לתחזק Skills לטכנולוגיה אחת במקום פעמיים."],"points":[],"kind":"idea"},{"title":"השפעה על הצוותים","body":["צוות קטן: 1 עד 2 מפתחים לכל Self-Contained System, עדיף שניים לצורך חילופי ידע, במקום 5 עד 7. אין Sprints אלא זרימה רציפה, ו-Use Cases משמשים בסגנון Kanban למעקב. ללא Pull Requests: עובדים על Trunk-based development, ו-Peer Review נעשה יחד, כשכל מפתח מסביר לשני את מה שנוצר.","המשמעות הגדולה: העבודה זזה שמאלה, לדרישות. במקום שבועיים דרישות ושבועיים מימוש, יש שבועיים ואז חמש דקות. בפרויקט של הפרלמנט הוא היחיד שנוגע בקוד ושני מהנדסי דרישות עובדים על המפרט ויש להם יותר עבודה ממנו. הוא בונה Pipeline שבו שינוי בקבצי המודל מייצר הכול אוטומטית."],"points":[],"kind":"idea"},{"title":"האם מייצרים דיאגרמה ב-PlantUML ומשם דרישות מפורטות?","body":"בפרויקט חדש יש קטלוג דרישות או מסמך מוצר, ממנו נוצרת דיאגרמת Use Cases שגם מרמזת איך לחלק למודולים. מהנדסי דרישות ו-Product Owners משתמשים ב-AI כדי לאמת Use Cases ולמצוא כפילויות וחסרים. הוא מדגיש שהם עובדים Use Case אחר Use Case ולא בסגנון מפל מים.","kind":"qa"},{"title":"אם הדרישה שגויה, מה הזרימה? מייצרים מחדש את כל האפליקציה?","body":"משנים את ה-Use Case או את מודל הישויות ומריצים שוב implement כדי להחיל שינוי, ולא זורקים את הקוד כדי לשמור על היסטוריית Git וקלות סקירה. הוא מוסיף שיש הטוענים ש-AI לא צריך קוד מקור (אולי אפילו bytecode), אך כרגע עובדים כמו בפיתוח ידני.","kind":"qa"},{"title":"איך מאמתים שהמימוש עדיין תואם את המפרט? (שאלה שנשאלה בהמשך, כנראה במסדרון)","body":"לפי הדובר יש skill שרץ בפייפליין וניהול drift: בודקים שהמימוש עדיין תואם ושהבדיקות שנוצרו אינן חסרות ערך. הוא מכנה זאת 'reflection' בתמלול הרשמי המשובש, ואומר שכך אפשר להתקדם יחסית מהר גם ביישומים קריטיים.","kind":"qa"},{"title":"כמה צריך להשקיע באימות?","body":"לדבריו בדיקות שנוצרות על ידי AI מתוך הקוד הן בעיקר בדיקות white box ואינטגרציה. לכן צוות בדיקות עובד גם הוא עם AI, מגדיר תהליכים ומייצר בדיקות Playwright מול האפליקציה הרצה (black box), כדי לוודא שתוצאת ה-use case נכונה. הטקסט הרשמי נקטע באמצע המשפט.","kind":"qa"},{"title":"שאלה חמישית על skills ועיבוד (גישה אחרת)","body":"השאלה מנוסחת בתמלול הרשמי בצורה משובשת, והתמלול נקטע באמצע השאלה; לא נמצאה תשובה זמינה ואין לשחזר אותה.","kind":"qa"},{"title":"מה נשאר מהסשן","body":[],"points":["מפרטים לא מספיקים בלי Harness: הקשר, Skills ומעקות בטיחות.","העבודה זזה שמאלה אל הדרישות, והידע בארכיטקטורה ובדומיין נשאר קריטי.","המפרט עשוי להישאר בר-קיימא גם אם הטכנולוגיה, ה-UI או הצורה (אפילו צ'אט) משתנים."],"kind":"idea"}],"diagram":{"kind":"flow","title":"AI Unified Process: ממפרט לקוד","nodes":[{"id":"v","label":"חזון ודרישות"},{"id":"s","label":"Use Cases + מודל ישויות (ירוק: המפרט)"},{"id":"u","label":"UI (Figma/MCP) או API"},{"id":"k","label":"Skills + Guardrails + MCP"},{"id":"c","label":"קוד ובדיקות (סדר לפי UI/API)"},{"id":"r","label":"סקירה לפי רמת סיכון"}],"edges":[{"from":"v","to":"s","label":"גזירה"},{"from":"s","to":"k","label":"במקום תוכנית ומשימות"},{"from":"u","to":"k","label":""},{"from":"k","to":"c","label":"implement"},{"from":"c","to":"r","label":""}],"caption":"סיימון מדלג על שלב התוכנית והמשימות של כלים כמו Kiro; ה-Skills ממלאים את התפקיד הזה."},"terms":[{"term":"Spec-driven development","definition":"פיתוח שבו מפרט (דרישות, Use Cases, מודל נתונים) הוא הקלט המרכזי ממנו נוצר הקוד, כאן בעזרת AI."},{"term":"System Use Case","definition":"תיאור התנהגות מערכת עם שחקן, תנאים מקדימים, תרחיש הצלחה, תרחישים חלופיים ותנאים מסיימים."},{"term":"Self-Contained System","definition":"סגנון ארכיטקטורה שמחלק את היישום לוורטיקלים עצמאיים הכוללים UI, לוגיקה ונתונים."},{"term":"Harness","definition":"כל ההקשר סביב הסוכן: Skills, הנחיות, MCP, מעקות בטיחות. בלשון הדובר: 'צריך את ה-harness'."}],"gaps":["התמלול אוטומטי ויש בו מילים משובשות (לדוגמה 'microgrid angel' לתיאור מסמך IREB, 'Tesla'); לא תוקנו בלי מקור.","אין צילום של שקפי הדובר או של הדמו, ורק מה שנאמר מתועד.","תיקון: בקובץ שסופק הסשן נסגר אחרי שתי שאלות, אך התמלול הרשמי מוסיף שלוש שאלות נוספות (Q3 עד Q5); Q5 קטועה באמצע ולא נענתה.","הטענות על מחקר מאוניברסיטת ציריך לגבי System Prompt גדול, על Use Cases ועל קבלת שיפור בצוותים הן דברי הדובר ולא נבדקו באופן עצמאי."],"source_refs":["https://www.youtube.com/watch?v=odbNXv9xXjc"]},{"number":17,"id":"HgA0spItnZI","url":"https://www.youtube.com/watch?v=HgA0spItnZI","type":"session","type_he":"סשן","duration":"32:17 דקות","title_he":"בני אדם מול קוד זבל: כללים חדשים לקוד פתוח","speaker_he":"ג׳ק וות׳רספון","summary":"ג'ק ווטרספון, Developer Advocate בגוגל שעובד על Gemini CLI (ובעבר על Google ADK), מתאר איך החוזה החברתי של קוד פתוח משתנה כשסוכנים מייצרים Pull Requests בלי שבן אדם התעמק בהם, ומציג כללים מעשיים מהמאגר של Gemini CLI ומעוד פרויקטים.","takeaways":["לדרוש Issue לפני PR, ובשינוי גדול להסכים עם מתחזק על התכנון. כך מפחיתים תיקונים שננטשים אחרי הערה ראשונה.","להגביל PR-ים פעילים לתורם חיצוני ולסגור פריטים ללא מענה באוטומציה. לפרסם כללים וציפיות לזמני תגובה.","לשמור הנחיות ו-Skills בריפו גם לכלים שאינם כלי הצוות. Skill ליצירת PR יכול להריץ בדיקות, למלא תבנית ולתעד שינוי.","לצרף צילומים או סרטון לשינוי חזותי. זו ראיה לביקורת שקל לבחון יותר מתיאור מילולי בלבד.","Open Source Vacation היא הפסקה זמנית בקבלת תרומות; Vouch הוא מנגנון המלצות וחסימות. אלה דפוסים שונים לניהול עומס ואמון, לא פתרון מלא.","התורם חייב להבין שינוי ולהגיב למשוב. בשאלות הקהל עולה המתח בין סינון לחניכת מפתחים חדשים, והדובר מדגיש מקום לשניהם."],"category":"קוד פתוח","coverage":"כל התמליל הזמין נסקר. בטקסט שסופק מופיעים גוף ההרצאה, הסיכום ושאלות מהקהל. אין כאן אימות מול הווידאו או הוכחה שלא חסרו קטעים באמצע. מחירי הסקה, היקפי PR-ים ויכולות GitHub הם טענות הדובר בזמן הכנס, לא נתונים עדכניים שאומתו.","source_basis":"תמלול מלא שסופק (קובץ מקור 3, פריט 2), כולל שאלות ותשובות. תמלול אוטומטי עם שגיאות זיהוי.","lead":"קוד הוא חינם, תחזוקה לא: חוקי משחק חדשים לפרויקטי קוד פתוח מול הצפת PRs שנוצרו על ידי AI","chapters":[{"title":"העולם הישן: חוזה חברתי בין בני אדם","body":["בעבר, כשמתחזק ראה issue הוא הניח שמשתמש אמיתי נתקל בבעיה, וכל Pull Request נכתב על ידי מי שחשב עליו. תורם חיצוני צפוי היה לקרוא תיעוד, לוודא שהבאג אינו באשמתו, להבין את הקוד, לתכנן, ולהגיב לסקירה. המתחזק מצדו הנחה ולימד.","לדברי ג'ק זה כבר לא המצב: לא ברור אם ה-PR הוגש על ידי סוכן ואם מישהו הסתכל על הקוד."],"points":[],"kind":"idea"},{"title":"למה הצפה: קוד חינם, סוכנים ומנויים מסובסדים","body":["סוכנים טובים במשימות ארוכות ורצים ימים (הוא מזכיר את הטרנד של /go). קוד הוא רק prompt ממך, והמנויים של החברות הגדולות מסובסדים: בעד 20 או 200 דולר אפשר לקבל הערכה של אלפי דולרים של הסקה, ולכן המשתמש לא מרגיש עלות.","הוא מביא דוגמה ש-GitHub Copilot מדד בקשות ולא טוקנים, ולפי דברי הדובר prompt אחד צרך מעל 60 מיליון טוקנים (שווי של כ-200 דולר ב-API) ובתוכנית של 30 דולר אפשר היה לקבל תיאורטית מעל 30,000 דולר. לדבריו GitHub שינה זאת באותו יום (נאמר מהבמה, לא נבדק)."],"points":[],"kind":"idea"},{"title":"נתוני סקאלה והנזקים שכבר קרו","body":"","points":["לפי הדובר, GitHub פרסם שמוזגו מעל 45 מיליון PRs בחודש ב-2025, ובחודש שעבר דובר על מעל 200 מיליון (דברי הדובר).","curl סבל מגל דוחות אבטחה מזויפים שנוצרו על ידי בוטים.","פרויקטים שמסרבים לקבל קוד שנוצר 100% על ידי AI, או סגרו PRs חיצוניים.","Ghostty משתמש במערכת vouch (בהמשך)."],"kind":"idea"},{"title":"שלוש בעיות מרכזיות","body":["Drive-by PR: מישהו מדביק stack trace לסוכן, מקבל תיקון תוך 30 שניות ומגיש. המתחזק נדרש לסקור ידנית (בגוגל עדיין סוקרים כל PR ידנית אחרי סקירה אוטומטית), והמגיש לא חוזר לענות. ה-PR נעלם.","מקביליות: סוכנים מקבילים מייצרים עשרה PRs בדקה, אבל בני אדם לא יכולים לסקור במקביל.","אמון: אי אפשר להניח שמי שהגיש מבין את הקוד. 'Claude אמר לי' אינו הסבר לשיקול דעת."],"points":[],"kind":"idea"},{"title":"הכללים החדשים ב-Gemini CLI","body":["הדובר מציין שהמאגר מונה 100,000 כוכבי GitHub ומעל 700 תורמים חיצוניים.","1. חובה לפתוח issue לפני PR, ולרוב מתחזק מאשר אותו. לדבריו זה מסלק כ-90% מה-drive-by PRs, כי סוכן או בוט לא חוזרים לפתוח issue.","2. הגבלת קצב: מספר מוגבל של PRs פעילים לתורם חיצוני. אפשר בעזרת GitHub Actions וכעת, לפי הדובר, GitHub מוציא הגדרה כזו בברירת מחדל. מתחזקים לא מושפעים.","3. אוטומציה: למשל סגירת issue אחרי 60 יום בלי תגובה, בלי צורך ב-AI.","4. קבצי הקשר במאגר: לא רק CLAUDE.md אלא גם AGENTS.md (או symlink), עם הוראות פשוטות כמו 'הרץ בדיקות' ו'מלא את תבנית ה-PR'.","5. Skills שמעלים את הרף גם לבני אדם: PR creator (קורא תבנית, מריץ בדיקות, מפרמט), docs writer (אוכף מדריך סגנון), code review. הוא מוסיף Skill אישי ב-Playwright שמצלם וידאו וצילומי מסך של שינוי: מתחזק שרואה וידאו ב-PR מבין יותר מהר ושם לב שהייתה מחשבה."],"points":[],"kind":"idea"},{"title":"מה עושים בקהילה: vacation, vouch ו-prompts","body":["Open source vacation: כמו הודעת out-of-office. PRs ו-issues באותה תקופה נסגרים אוטומטית עם הודעה, ועם תאריך סיום. מריו, מפתח Pi coding agent, משתמש בזה גם כשהוא לא בחופשה כדי להוריד את הבאקלוג לאפס.","vouch: מערכת הפניה של מיטשל האשימוטו (ממייסדי Terraform/HashiCorp) ב-Ghostty. מתחזקים או תורמים מהימנים 'מערבים' אחרים, ומי ששלח קוד גרוע מקבל denounce וחסום. הקובץ נבדק על ידי GitHub Actions, וברירת המחדל לאלמוני נקבעת בהגדרות. לפי הדובר, מיטשל אמר שאיכות ה-PRs עלתה מאוד והוא עדיין מקבל PRs, כלומר המערכת מסננת את הרעים.","'prompts הם ה-PRs החדשים': יש שמבקשים לשלוח את הכוונה והפרומפט ולא את הקוד. ג'ק אומר שלא התקדם עד לשם והוא חושב שזה קשוח, אבל חברות גדולות משתמשות בזה."],"points":[],"kind":"idea"},{"title":"מדריך למתחזקים ולתורמים","body":"","points":["מתחזקים: issue קודם, הגבלות לתורמים חיצוניים, הקשר ו-Skills לשיפור כל הסוכנים, אוטומציה ואמון דרך vouch.","תורמים: הבינו מה נכתב לפני הגשה, ענו על ביקורת, היו מוכנים להסביר החלטות, ותצפו לקצת התנגדות.","הוסיפו ל-CONTRIBUTING סעיף 'הנחיות לסוכנים/AI'. גם אם סוכנים לא תמיד מצייתים, זה מסנן חלק מהם.","העיקרון: אמון, מבנה (Skills וקבצי הקשר), כבוד. 'העתיד הוא שיתוף פעולה בין בני אדם וסוכנים'."],"kind":"idea"},{"title":"האם החסימות לא פוגעות בזמן התגובה לתורמים אמיתיים?","body":"זו שאלת שיקול דעת. האוטומציה נועדה לסנן רעים כדי שהמתחזק יוכל להשקיע בטובים, וכדאי לפרסם ציפיות (למשל זמן תגובה של יומיים) במאגר.","kind":"qa"},{"title":"האם יש מודלים עסקיים, כמו תשלום על תמיכה?","body":"הוא לא ראה חברות משלמות על מסלול מהיר ב-Gemini CLI: הכול דרך GitHub ומטופל שווה. ההמלצה לפרויקטים קטנים: הגדרת SLA ואוטומציה שמתריעה כשמתקרבים אליו.","kind":"qa"},{"title":"אולי עדיף לחנך ולא רק לחסום, כי מי ילמד את הג'וניורים?","body":"הוא מסכים שזו שאלה לכל התעשייה ומעודד מנטורינג מכוון, כולל Summer of Code. Skills כמו PR creator נועדו להעלות את הרף של תורמים חדשים.","kind":"qa"},{"title":"איך מונעים עומס הקשר מ-Skills רבים?","body":"הכלל שלהם: Skill שמשתמשים בו ביותר מ-50% מהזמן (כמו יצירת PR) מופעל כברירת מחדל; אחרת מוגדר כפקודת slash או כלל.","kind":"qa"},{"title":"מה נשאר מהסשן","body":[],"points":["תחזוקה היא צוואר הבקבוק האמיתי, לא יצירת קוד.","אין עדיין playbook מוסכם. ג'ק מסכם מה שנוסה בפועל.","יש לשלב בקרות אוטומטיות עם הנחיות ברורות כך שגם בני אדם וגם סוכנים יוכלו לעמוד בהן."],"kind":"idea"}],"diagram":{"kind":"layers","title":"שכבות הגנה על מאגר קוד פתוח","nodes":[{"id":"i","label":"issue לפני PR (מסנן drive-by)"},{"id":"r","label":"הגבלת PRs פעילים לתורמים חיצוניים"},{"id":"a","label":"אוטומציה: סגירת issues ישנים, סקירות"},{"id":"c","label":"AGENTS.md / CLAUDE.md + Skills (PR creator, docs)"},{"id":"t","label":"אמון: vouch / denounce, open source vacation"}],"edges":[{"from":"i","to":"r","label":""},{"from":"r","to":"a","label":""},{"from":"a","to":"c","label":""},{"from":"c","to":"t","label":""}],"caption":"סדר השכבות הוא בניית ההרצאה, לא דירוג שהדובר נתן."},"terms":[{"term":"Drive-by PR","definition":"Pull Request שהוגש ללא כוונה לעקוב אחריו, לרוב מיוצר על ידי סוכן ו-stack trace."},{"term":"Open source vacation","definition":"מנגנון שסוגר אוטומטית PRs ו-issues בתקופה מוגדרת עם הודעה."},{"term":"vouch","definition":"קובץ במאגר ורשימות מהימנים ונדחים, כך שמי שלא הומלץ לו מוגבל בהרשאות."},{"term":"Context files","definition":"קבצים כמו AGENTS.md ו-CLAUDE.md שמסבירים לסוכנים איך לתרום לפרויקט."}],"gaps":["התמלול אוטומטי ויש בו שגיאות (למשל 'Macy' כשם המנחה, 'Pi coding agent Mario').","התמלול מסתיים בשאלות אחרונות ובסגירת המנחה ללא הפסקה חסרה.","לא ניתן לראות את השקפים או את הדמו.","מספרי GitHub (45 מיליון, 200 מיליון), הפרשת Copilot ו-60 מיליון טוקנים, הדיווח על curl ושיפור האיכות ב-Ghostty הם דברי הדובר, לא אומתו מול מקור חיצוני."],"source_refs":["https://www.youtube.com/watch?v=HgA0spItnZI"]},{"number":18,"id":"-sYhcsy5OwI","url":"https://www.youtube.com/watch?v=-sYhcsy5OwI","type":"session","type_he":"סשן","duration":"32:31 דקות","title_he":"איך צוותי AI הופכים טעויות מיוחסות לידע משותף","speaker_he":"אדואר מאליקס","summary":"אדוארד מלה, יועץ עצמאי למנהלי טכנולוגיה, בונה תשתית קוד פתוח ניסיונית שמלכדת תיקונים וטעויות של סוכני קוד לידע משותף של הצוות, תוך שמירה על שיוך (attribution) של כל החלטה. הוא מדגיש שהכול ניסיוני.","takeaways":["זהות נפרדת מאפשרת ייחוס שינויים והרשאות עצמאיות, במקום הסתרת פעולה אוטומטית מאחורי זהות וחתימת מפתח.","יומן שומר תקלות והחלטות עם קישורים ל-PR, לביקורת ולתיקון. מפרידים היקף אישי, צוותי, פרויקטלי וריפו.","אוספים אירועים, מאתרים דפוסים חוזרים ומרכיבים חבילת ידע קטנה. מרנדרים ל-Markdown בתקציב הקשר ושומרים ייחוס לכל מקור.","בודקים בנפרד נאמנות לאירועים, תועלת במשימה והפעלה בזמן. שופט LLM דורש כיול אנושי של הנחיות וקריטריונים לפני שמאמינים לציונו.","משחזרים תקלה אמיתית, כמו SDK בשפת Go שלא עודכן אחרי שינוי API, ומשווים עבודה עם ובלי חבילת ידע.","מריצים הערכות בסביבה נשלטת עם גבולות קבצים ורשת. בודקים שוב כשהקוד והמודל משתנים ומוציאים חבילות שכבר אינן מועילות."],"category":"הקשר וזיכרון","coverage":"כל התמליל הזמין נסקר. בטקסט שסופק מופיעים גוף ההרצאה, הסיכום ושאלות מהקהל. אין כאן אימות מול הווידאו או הוכחה שלא חסרו קטעים באמצע. הגישה מוגדרת במפורש כניסוי. דוגמת ה-SDK היא תוצאה נקודתית שהדובר מציג, לא הוכחה כללית.","source_basis":"תמלול מלא שסופק (קובץ מקור 3, פריט 3), כולל שאלות ותשובות. הכותרת במקור קטועה ('One Attributed Mistake at...'), ולכן המשפט 'one mistake at a time' מושלם כאן מהכותרת הקטועה ואינו נאמר בתמלול.","lead":"לקחים שנוצרו בשיחה עם סוכן לא צריכים להיעלם: זהות לסוכן, יומן, חבילות ידע והערכה","chapters":[{"title":"הבעיה: לקחים נשארים בתוך סשן","body":["סוכנים כבר כותבים, סוקרים ואפילו מתכננים ספרינטים, אבל תיקונים קטנים ('לא ככה') נשארים בסשן סגור. כשיוצרים Skills, כללים והערות פרויקט הם מצטברים כמו חלון הקשר עמוס, ואי אפשר לדעת אם הם עדיין שימושיים, מיושנים או בכלל מופעלים.","בסקירת PR, גם כשהבדיקות ירוקות והתיאור טוב, אי אפשר לדעת אילו לקחים עיצבו אותו. הוא מציע 'מפעל ידע' (knowledge factory): מערכת שתופסת טעויות והפרעות, הופכת אותן להנחיות, בודקת אם הן עוזרות, ומקבלת שחלק מהידע ייכשל או יתיישן כשהמודל או הקוד משתנים."],"points":[],"kind":"idea"},{"title":"פרימיטיב 1: זהות לסוכן","body":["הוא מראה PR שפתח לפני חודש לתוסף של פרויקט פופולרי. המתחזק לא היה ידידותי לסוכנים ולכן הוא הסתיר עקבות של Claude Code. לדבריו כ-95% מה-PR נכתב על ידי Claude, וכל ה-commits תחת שמו (כולל חתימת GPG): 'האשליה מושלמת', וזו הבעיה. הוא שואל גם על סקירות PR שנכתבו על ידי Claude Code אבל הגיעו מחבר צוות: 'האם זה לא מעליב?'.","הפתרון הראשון: לתת לסוכן זהות נפרדת (למשל GitHub App עם commits חתומים). כך הסוכן לא מסתתר מאחורי שם האדם, ואפשר להגדיר לו גישה והרשאות משלו במקום ירושה מהרשאות אדם."],"points":[],"kind":"idea"},{"title":"פרימיטיב 2: היומן (Diary)","body":["שיוך אומר מי פעל אבל לא למה. היומן הוא המקום שבו לקחים והחלטות נשמרים לפני שנעלמים. הוא מאפשר גבולות גישה: יומן משותף לצוות, יומן אישי, ויומן ברמת מאגר או פרויקט.","ב-commit של הסוכן יש הפניה לרשומה ביומן עם נימוק העבודה, כך שאפשר ללכת מעבר ל-diff והודעת ה-commit. הרשומות מחולקות לארבע קטגוריות; בדוגמה הוא משתמש בקטגוריה אפיזודית ('רגע של WTF'). הטקסט עצמו לא מפרט את שמות הארבע אלא רק מציג אותם בשקף."],"points":[],"kind":"idea"},{"title":"מיומן לידע: קליטה פסיבית, חקירה וחבילות","body":["דוגמה נוספת: סוכן שהשתמש בשיטה לא נכונה של דרייבר DB שהחמיצה את סשן הטרנזקציה. הרשומה נוצרה לבד, ואז נקשרה להערת ה-PR ולתיקון, כך שגם אחרי חצי שנה אפשר להגיע לתיקון ולשיעור.","שלב ראשון: צבירה פסיבית של רשומות. שלב שני: אצירה. מגלים מה יש, ממפים תחומים, פורסים לאירועים, בודקים קשרים ואם צריך חיפוש גולמי (RAG). כשיש נושאים אפשר לבנות Pack: חבילה קטנה של רשומות לאזור ספציפי, 'לא שק צעצועים אלא תערוכת גלריה'. הראשונה הייתה על תרגולי בסיס נתונים בפרויקט שלו עצמו.","לפני שהסוכן קורא אותה, מרנדרים את החבילה לקובץ Markdown: הסוכן שולף את הרשומות, קוצץ לתקציב טוקנים, וכל מקטע שומר הפניה למקור, זיהוי הרשומה, האדם והסוכן. כך זה לא 'כך עושים' אלא 'כך עושים כי נפגענו'."],"points":[],"kind":"idea"},{"title":"הלולאה ו'הנדסה מצטברת'","body":["הלולאה: הפרעה הופכת לרשומה, רשומות הופכות ל-Pack, Pack הופך למשהו שהסוכן קורא, והלקח שאדם או סוכן שילם עליו הופך לנכס של הצוות. הוא מציין שיש דיסציפלינה כזו שנקראת, לדבריו, compound engineering.","בצוות אנושי מי שמחליט מה שורד הוא ADR, ויקי, סקירות קוד ופוסטמורטמים, אבל בקצב אנושי. סוכנים מייצרים תיקונים מהר יותר ממה שהמערכות קולטות, ולכן צריך כלי שיפוט."],"points":[],"kind":"idea"},{"title":"הערכה: נאמנות ושימושיות, בסביבה מבוקרת","body":["הוא שואל שתי שאלות על Pack: האם הוא נאמן לרשומות (כולל הכול, בלי עיוות) והאם הוא עוזר בתרחיש אמיתי. (שאלת ההפעלה נשארת מחוץ להרצאה.) הוא מדגיש להריץ שופטי LLM בסביבה מבוקרת בתוך sandbox/VM שבה קובעים לאילו קבצים ורשת יש גישה, כדי שאין דליפה.","כל משימת הערכה מקבלת תבנית פרומפט, קריטריונים ודוגמאות ייחוס. בדוגמה שלושה קריטריונים בינאריים נתנו ציון משולב כמעט מושלם, ושם הוא מזהיר: פרומפט עצלן או קריטריונים לא מכוילים מייצרים תחושת ביטחון כוזבת. לכן קודם אתה עצמך 'השופט': עושה ידנית את מה שהשופט יעשה.","לשימושיות: מריצים משימה שמשחזרת תקרית קיימת עם Pack וללא Pack ובודקים את ההפרש. בתרחיש ה-Go SDK, בלי Pack נכשלו בכל ריצה (בתמלול 'we fail at 67 every time', מספר לא ברור) ועם Pack עברו תמיד גם בחזרה על המשימה."],"points":[],"kind":"idea"},{"title":"אוטונומיה: סוכנים שבוחרים משימות והאדם שומר שיפוט","body":["כדי לצעוד לעבר סוכנים אוטונומיים צריך קודם להיפרד מהצורך של הסוכן 'לרַצות' אותנו. אפשר להשאיר דלי משימות ולתת לסוכנים עם יכולות מתאימות לבחור מרצון. השיוך נשמר לכל משימה כך שהידע והתיקון נבנים מהר יותר.","האדם נשאר עם המטרה, השיפוט והאחריות; הסוכנים עם הרציפות, החזרתיות והעבודה הכבדה. אפשר לדמיין סוכני מקודד, מבקר וניהול, ושאמון ייבנה כמו אצל תורמים בחברה."],"points":[],"kind":"idea"},{"title":"האם זה מקביל ל-MemPalace או רעיונות דומים?","body":"יש רכיב זיכרון, אבל הוא לא השקיע בשיפור אחסון ושליפה: חשוב לו יותר לספק פרימיטיבים וכלים לתהליך המלא, כי זיכרון לבד לא פותר שיתוף ידע בין צוותים. (שם הפרויקט בשאלה מתומלל כ'Palace'.)","kind":"qa"},{"title":"האם יש מקרי קצה, כי החיים מורכבים יותר ממקרה פשוט?","body":"זה לא מיידי. הרשומה נשארת והתיקון יכול להגיע ביום אחר. אם התקרית לא חוזרת היא חד-פעמית; אם חוזרת, יוצרים קשרים ומאחדים את התהליך.","kind":"qa"},{"title":"איך מתחזקים את הידע כשהקוד והמוצר משתנים?","body":"כמו Skills: הרשומות רק מצטברות, וה-Pack המרונדר הוא קובץ Markdown שהופך ל-Skill. מריצים evals סדירים עם המודל של הצוות ומה שלא מועיל נמחק. האצירה מתחילה ידנית ורק כשמבינים את הדפוס מאצילים לסוכנים: 'אם אתה לא יכול להסביר, איך תצפה ממודל לעשות'.","kind":"qa"},{"title":"מה נשאר מהסשן","body":[],"points":["שאלת הסיום של הדובר: מה הסוכנים שלך למדו אתמול שהצוות שלך עדיין יודע היום.","שיוך, יומן, אצירה והערכה הם השלבים; כולם ניסיוניים לדברי הדובר.","האדם שומר שיפוט ואחריות."],"kind":"idea"}],"diagram":{"kind":"loop","title":"לולאת הידע: מטעות לנכס צוותי","nodes":[{"id":"e","label":"הפרעה/תיקון בסשן"},{"id":"r","label":"רשומת יומן עם שיוך (אדם + סוכן)"},{"id":"p","label":"Pack נושאי (אצירה)"},{"id":"m","label":"רינדור ל-Markdown/Skill עם הפניות למקור"},{"id":"v","label":"הערכה: נאמנות + שימושיות (עם/בלי Pack)"},{"id":"a","label":"נכס צוותי"}],"edges":[{"from":"e","to":"r","label":"נשמר"},{"from":"r","to":"p","label":"אצירה"},{"from":"p","to":"m","label":"תקציב טוקנים"},{"from":"m","to":"v","label":"sandbox"},{"from":"v","to":"a","label":"שורד או מת"}],"caption":"בהרצאה הרכיבים הם פרימיטיבים לניסוי, לא מוצר סופי."},"terms":[{"term":"Attribution","definition":"שיוך מי עשה (אדם וסוכן) ומה הנימוק, כך שאפשר לבדוק בדיעבד."},{"term":"Diary / Entry","definition":"היומן של הצוות והרשומות שבו, כל רשומה היא אירוע, החלטה או לקח."},{"term":"Pack","definition":"חבילה קטנה ומסודרת של רשומות לנושא אחד שמרונדרת לסוכן."},{"term":"LLM judge","definition":"מודל שמעריך פלט לפי קריטריונים; דורש כיול ידני כדי לא לתת ביטחון שווא."},{"term":"Compound engineering","definition":"כפי שהוזכר: דיסציפלינה של צבירת לקחים שמצטברים לאורך זמן."}],"gaps":["ארבע קטגוריות הרשומות מוצגות בשקף ולא נאמרות בתמלול.","המספר '67' בתוצאת ההערכה לא ברור בתמלול, ולא נקבע מה הוא מייצג.","התמלול נקטע במילה 'go get' בסוף ההפסקה (מעבר לפריט הבא); אין תוכן חסר מהרצאה עצמה.","התוצאה של Go SDK עם/בלי Pack היא תוצאה מהדגמה אחת של הדובר, ללא פירוט מדגם."],"source_refs":["https://www.youtube.com/watch?v=-sYhcsy5OwI"]},{"number":19,"id":"-6SNbcE3C9o","url":"https://www.youtube.com/watch?v=-6SNbcE3C9o","type":"session","type_he":"סשן","duration":"31:16 דקות","title_he":"מנקודות עיוורון ל-PR ממוזג: סוכנים שמבינים ביצועים בייצור","speaker_he":"מיי וולטר","summary":"מיי וולטר, מייסדת שותפה של חברה שבונה 'שכבת Runtime Intelligence' לסוכני קוד, מספרת איך ניסו לבנות סוכן שמזהה אופטימיזציות ביצועים בפרודקשן. היא מתארת מה לא עבד (PRs שאף אחד לא סוקר), מה כן (הקשר פרודקשן ברמת פונקציה, Skills, דירוג ROI) ומה לקחו מזה.","takeaways":["חקירה שבועית או דו-שבועית מחזירה הזדמנויות מדורגות. בדוגמה GitHub Agentic Workflows מריץ סוכן עם נתוני Hud ושולח דוח ל-Slack.","מיפוי Prod-to-Code מחבר Endpoint או משימה לפונקציות, תדירות הרצה, משך וכשלים. אפשר לשאול למה פעולה איטית וגם על מה ישפיע שינוי.","מביאים מידע פורנזי מפורט רק באזור הרלוונטי במקום להזרים הר של לוגים. מעל שכבת השאילתות נבנים Skills לחקירת שגיאת 500, דליפת זיכרון או האטה.","תיקון סביר אינו תיקון מוכח: תפיסת Exception עלולה להסתיר סימפטום. שאילתה איטית מחייבת להבין נתונים ומסלול קריאה, לא רק תחביר.","מחפשים השפעה גבוהה וסיכון נמוך, למשל N+1 או המתנות מלאכותיות, ומחברים למסלולים חשובים לעסק כמו תשלום ואימות.","במקום עשרות PR-ים ללא בעלות או עדיפות, מציגים גודל שינוי, השפעה וסיכון ונותנים לצוות לבחור חקירה, כרטיס או PR. אחרי פריסה מודדים השפעה."],"category":"עלות וביצועים","coverage":"כל התמליל הזמין נסקר. בטקסט שסופק מופיעים גוף ההרצאה, הסיכום ושאלות מהקהל. אין כאן אימות מול הווידאו או הוכחה שלא חסרו קטעים באמצע. יכולות המוצר ושיפורי האחוזים הם תיאור הדוברת וניסיון לקוח, לא התחייבות לתוצאה.","source_basis":"תמלול מלא שסופק (קובץ מקור 3, פריט 4), כולל שאלה אחת בסוף. התמלול אוטומטי; שם החברה מתומלל 'hood' או 'Hud's'.","lead":"סוכן שחוקר ביצועים בפרודקשן ומעלה הזדמנויות מדורגות לבני אדם, במקום להציף ב-PRs","chapters":[{"title":"הבעיה: 'האתר איטי' ואף אחד לא יודע כמה זה עולה","body":["התרחיש: מנהלת מוצר אומרת שעמוד איטי, מנהל הנדסה עונה 'כנראה, אבל צריך לבדוק', ואחרי שבועות זה הופך למשבר. 'כמה זמן ייקח?' 'בין שעה לשבוע', ומי יכול לטפל? רק דייב, כי רק הוא מכיר את הקוד. לקוח אחד היה בדיוק במצב הזה: 'צריך לתקן, אין לנו מושג איך, ואי אפשר לתעדף'.","היא מתארת דלי דולף: כולם עסוקים בבניית פיצ'רים, מתעלמים, ואז המשבר מתעדף. בעיית המחקר היא המכשול, 'כמו לקחת מוצר בסופר וללכת לקופה רק כדי לדעת כמה הוא עולה'. הרעיון היה לאוטמט את החקירה (לא התיקון) כדי לדעת מה אפשר לעשות ובאיזה ROI, ולהריץ 'ספרינט ביצועים' שבועי."],"points":[],"kind":"idea"},{"title":"מה הם בונים: חיישן בפרודקשן","body":["החברה בונה חיישן שרץ עם האפליקציה בפרודקשן ולוכד מה שסוכני קוד צריכים כדי לחשוב על פרודקשן: לכל פונקציה, כמה פעמים רצה, כמה זמן לקחה והאם נכשלה, ובעת תקלה הקשר פורנזי עמוק.","היא מסבירה שהקוד קל לייצר, סוכן אחד בונה וסוכן אחר אומר 'נראה טוב', ובכל זאת הקוד נכשל בפרודקשן בדרכים יצירתיות כי לסוכני הקוד אין מושג איך הוא מתנהג שם."],"points":[],"kind":"idea"},{"title":"איפה זה רץ: GitHub Agentic Workflows","body":["דרישות: לא על המחשב המקומי, ענן ניטרלי לספק (לא נעול ל-Cursor או לפלטפורמה אחת), בחירה חופשית של coding agent ומודל, אבטחה (הרשאות, קריאות כלים, אימות) בלי לבנות מאפס, טריגרים (webhooks או לוחות זמנים) ותחזוקה קלה: 'סוכנים הם כמו קוד, לא רק משגרים אותם'.","הם בחרו GitHub Agentic Workflows כי ללקוחות כבר יש GitHub Actions. היא מציינת שמי שבנה את הכלי נמצא בקהל. ההגדרה: בוחרים engine (Claude, Codex...), הרשאות, רשת, כלים, שרת ה-MCP של החברה, ו'משימה' שהיא פרומפט שרץ מדי פעם או בטריגר. בפועל זה דוח שבועי של 'מהנדס ביצועים ואמינות' ל-repo, ואף לפי שירות לטק ליד הרלוונטי. סוכן (במקרה זה Claude) רץ שבועית ב-GitHub Actions ושולח דוח ל-Slack."],"points":[],"kind":"idea"},{"title":"זרימת העבודה המתוכננת","body":["הקשר פרודקשן, ניתוח אנטי-פטרנים והזדמנויות, דירוג ו'דגל' (לא כל מה שאפשר לעשות צריך לעשות, כי צריך לסקור ולמזג ולא רוצים סיכון בפריסה ללא השפעה), PR וסקירה אנושית. היא מזהירה שבביצועים נוטים להתחיל מהשערה, לתקן, ואז בפרודקשן ההשפעה קטנה ממה שציפו."],"points":[],"kind":"idea"},{"title":"למה זה לא עבד בהתחלה","body":["שפת הפרודקשן (שירות או endpoint, P99) שונה מהשפה שהסוכן חושב בה (פונקציות וקבצים). היא אומרת שאוטומציה שעובדת 90% מהזמן היא 'זרימה לבני אדם' ולא אוטומציה."],"points":["הצעות סבירות אבל לא מאומתות: 'אפשר כנראה לשפר' בלי לדעת מה הצוואר האמיתי.","שאילתות מורכבות ותלויות בנתונים (10,000 שורות אצל לקוח אחד).","ה'תיקון העצל': תופסים exception ומחביאים. תיקון מקומי במקום תמונה רחבה.","ההקשר: או יותר מדי או חסר. מהנדס היה מוסיף לוגים ומדדים ומפעיל גרסה; הסוכן נוקט בקיצור דרך והנחות. לא ניתן להרשות זאת כשמפריעים לזרימת מהנדסים: דוח שגוי מבזבז זמן ומאבד אמון."],"kind":"idea"},{"title":"Prod to code: מיפוי פרודקשן לרמת פונקציה","body":["הפתרון: מיפוי מה שקורה בפרודקשן לרמת הפונקציה: endpoint או שירות, צרכני אירועים, cron jobs, והפונקציות המעורבות. זה מאפשר לשאול 'למה איטי' וגם את ההפוך: 'אם אני נוגע בזה, מה מושפע, האם זה משפיע על תשלומים והרשאות?'.","הם לא טוענים לוגים וטראסים בגיגה-בייטים, אלא קודם מקשרים לכל פונקציה תדירות, זרימות עסקיות, זמן וכשלים, ורק אז נכנסים להקשר עמוק (לוגים, טראסים). הם משתמשים ב-ClickHouse כשכבת שאילתות, ומעליה Skills: איך מטפלים ב-HTTP 500, בדליפת זיכרון, בהידרדרות ביצועים; ומעל זה אוטומציות כמו auto fix והסרת קוד מת."],"points":[],"kind":"idea"},{"title":"Skills: מתודולוגיה במקום שהסוכן ימציא","body":["היא מדגישה שכלים לא מספיקים. דוגמה: בדליפת זיכרון, להשוות pod עם דליפה ל-pod בלי דליפה. הם מנחים: חפשו sleeps ו-timeouts מלאכותיים, שאילתות N+1, אינדקסים חסרים, חסימה סינכרונית, awaits רציפים. בבסיס קוד בן 15 שנה כל אלה קיימים ('זה היה ככה שש שנים?!').","תוצאה: שאלה 'למה ה-endpoint איטי' מחזירה, למשל, 'יש N+1 שקיים בקוד שש שנים'."],"points":[],"kind":"idea"},{"title":"הלקח הגדול: לשכנע את האדם, לא את הסוכן","body":["בהתחלה פתחו PRs אוטומטית לכל שינוי בעל השפעה גבוהה וסיכון נמוך. אף אחד לא התייחס: '80 PRs' הם כמו 700 issues ב-Sentry או Datadog. 'אנחנו בנאים, יש תעדוף'. לכן שינו: ממפים hot paths, השפעה עסקית (תשלומים/אימות), וסיכון, ומחפשים 'ההשפעה הכי גבוהה, הסיכון הכי נמוך' ולא את האופטימיזציה הכי טובה.","התוצאה צריכה להיות קריאה לאדם, למשל: 'ב-endpoint הזה P90 הוא כ-100 מילי-שניות, אבל לפעמים 45 שניות, ואם תחליפו פונקציית distinct ב-Mongo ל-search, זה ישפר 30 עד 40%'. מכאן בני אדם בוחרים: לחקור יותר, לפתוח ticket או PR, ושניהם מתויגים כדי למדוד."],"points":[],"kind":"idea"},{"title":"אנשים כבר מחוברים ל-Datadog או Sentry, אז איך נשארים תחרותיים אם גם אתם צריכים נתונים?","body":"היא משתמשת במטפורה של חנות אספרסו: עושים דבר אחד הכי טוב. שואלים אם הלקוח עדיין סובל מתקלות ומבוכה מבעיות שלקוחות מדווחים עליהן, ומתחברים לכלים הקיימים (כמו distributed tracing). הערך שלהם הוא הקשר ברמת פונקציה והקשר פורנזי שנלכד באופן יזום.","kind":"qa"},{"title":"מה נשאר מהסשן","body":[],"points":["להגדיר מה חשוב: מה שווה טוקנים, זמן וסקירה אנושית.","לאוטמט את החקירה כדי לשפר תעדוף, לא כדי לרוקן את ה-backlog.","הקשר עדיף על חכמה; פחות ופרטיים נכונים עדיף על הרבה בעלי ספק, כי כל המלצה שגויה שוחקת אמון.","אוטומציה דורשת ביטחון גבוה, והדוברת חולמת על 'מיזוג בלחיצה' כשמדדים 80% הצלחה."],"kind":"idea"}],"diagram":{"kind":"stack","title":"שכבות הידע שמאפשרות לסוכן ביצועים להיות אמין","nodes":[{"id":"s","label":"חיישן פרודקשן: תדירות, זמן, כשלים לכל פונקציה"},{"id":"m","label":"Prod-to-code: מיפוי endpoint/cron לפונקציות"},{"id":"q","label":"שכבת שאילתות (ClickHouse)"},{"id":"k","label":"Skills: 500, דליפת זיכרון, ביצועים"},{"id":"a","label":"אוטומציות: דוח שבועי, auto fix, קוד מת"},{"id":"h","label":"אדם: ROI, סיכון, אישור PR"}],"edges":[{"from":"s","to":"m","label":""},{"from":"m","to":"q","label":""},{"from":"q","to":"k","label":""},{"from":"k","to":"a","label":""},{"from":"a","to":"h","label":"דירוג ו'דגל'"}],"caption":"התרשים מסכם את מה שהדוברת תיארה, לא מצג שלה."},"terms":[{"term":"Runtime intelligence","definition":"הקשר שנאסף בזמן ריצה בפרודקשן (תדירות, זמנים, כשלים) כדי שסוכנים יסיקו מסקנות מבוססות מציאות."},{"term":"Prod to code","definition":"מיפוי בין מה שקורה בפרודקשן (endpoint, cron) לפונקציות בקוד."},{"term":"Lazy fix","definition":"תיקון שטחי, כמו לתפוס exception, שלא מטפל בבעיה הרחבה."},{"term":"GitHub Agentic Workflows","definition":"מנגנון שמריץ סוכנים כתהליכי GitHub Actions עם טריגרים והרשאות."}],"gaps":["לא נמסרו נתונים מספריים מוצקים על כמה PRs מוזגו או ירידת זמן ממוצעת.","שם החברה והלקוח אינם ברורים בתמלול.","אין שקפים או דמו בתמלול.","התוצאות של הלקוח ('שש שנים', שיפור 30 עד 40%) הן דוגמאות והערכות של הדוברת, לא מדדים מדווחים."],"source_refs":["https://www.youtube.com/watch?v=-6SNbcE3C9o"]},{"number":20,"id":"mB74LGAmmV0","url":"https://www.youtube.com/watch?v=mB74LGAmmV0","type":"session","type_he":"סשן","duration":"36:51 דקות","title_he":"יותר תוכנה, מהר יותר: הטרנספורמציה של Odevo","speaker_he":"דניאל ג׳ונס ותומאש מאי","summary":"דניאל ג'ונס (יועץ בוטיק re:cinq, לשעבר מקינזי לפי דבריו) ותומאש מאי (Odevo, חברת ניהול נכסי מגורים) מספרים איך אימנו את כל המפתחים בארגון על קידוד עם סוכנים ומה השפיע על התוצאות.","takeaways":["לפני ההדרכה בחנו CI/CD, פלטפורמה, בדיקות וסטנדרטים. האצת הקוד חושפת חולשות בתהליך ולא מתקנת אותן מעצמה.","סדנאות פנים אל פנים חשפו חששות. תרגיל TRIZ ביקש לתכנן כיצד להכשיל קליטת מפתחים שלעולם אינם אומרים לא, ואז לזהות התנהגות דומה בארגון.","התחילו בפיילוט ובמפגשי חצי יום שבועיים עם יישום בקוד האמיתי ביניהם. נדרש תיאום הרשאות התקנה ו-IT מראש.","לימדו מגבלות הקשר, הזיות והטיות לפני MCP, מפרטים וריבוי סוכנים. ציור משותף של מה שקרה בתרגיל בנה הבנה ולא רק זיכרון פקודות.","צוות אחד התחיל בשיחות מוצר מתומללות, דרישות ומודל תחום. בחירתו בביקורות אוטומטיות ובמיזוג עצמי היא תיאור מקומי, לא הנחיה לכל ארגון.","בנו מדריכים פנימיים וצוות מגדלור לשיתוף. בהמשך הכשירו אנשי מוצר וזיהו לחץ להספק וקושי להפסיק לעבוד."],"category":"מוצר וארגון","coverage":"כל התמליל הזמין נסקר. התמלול מגיע לסיום. הדוברים מציינים שאין זמן לשאלות ומפנים לשיחה לאחר ההרצאה. אין אימות לכל דקה בווידאו. 94% אימוץ, שכתוב בשלושה שבועות וצמצום צוות הם דיווחי הדוברים, לא תוצאה מאומתת או ניסוי מבוקר. מספרי תפוקה משובשים בתמלול לא הועתקו.","source_basis":"תמלול מלא שסופק (קובץ מקור 3, פריט 5). אין שאלות ותשובות: ההרצאה נקטעה בלחץ זמן לפני ארוחת צהריים. תמלול אוטומטי עם שגיאות.","lead":"אימון מפתחים בפיזית, יסודות לפני סוכנים, ומדידת הצלחה לפי כמה דברים נועזים עושים","chapters":[{"title":"Odevo: ארגון מבוזר שצומח במהירות","body":["Odevo היא חברת ניהול נכסי מגורים שמספקת גם שירותים ותוכנה, ולדברי הדוברים דורגה שלישית בחברות הטכנולוגיה הפרטיות בשוודיה. בשבע שנים צמחה, לפי דבריהם, מ-50,000 ל-2.5 מיליון בתים בניהול ומ-1,000 ל-14,000 עובדים, בעיקר ברכישות (לפעמים משפחה קטנה שמנהלת נכסים). נוכחת בשוודיה, בריטניה, ארה״ב ומקסיקו.","התוצאה: ארגון הטרוגני מאוד עם טכנולוגיות, תרבויות ותהליכים רבים, חלקן תוכנות ישנות, לפעמים ללא UI, ובחלק מהשווקים עדיין נייר. לדברי תומאש, המשתמשים כמה מהם מתנדבים עם מעט ידע, ולכן תוכנה טובה משפרת חיים."],"points":[],"kind":"idea"},{"title":"נקודת פתיחה בשנת 2024","body":["תומאש הצטרף ב-2024. המפתחים השתמשו ב-GitHub Copilot (כ-30% אימוץ), היה כלי צ'אט פנימי על OpenAI API בגלל נתוני לקוחות רגישים, וכמה 'איי Claude' של מפתחים בודדים. PRs היו גדולים ונדירים, וצוותים לא ידעו שהם איטיים.","במשך שנה וחצי הם שיפרו שיטות עבודה, זרימה ושקיפות. לדבריו זה הקל מאוד על האימון בהמשך."],"points":[],"kind":"idea"},{"title":"בחירת שותף לאימון","body":["הם החליטו להכשיר כל מפתח בארגון באותה צורה. הם פרסמו ב-LinkedIn וקיבלו כ-80 פניות (ובדיחה על 'בני 15 עם 25 שנות ניסיון'), צמצמו לעשר, ואז לשלוש חברות, ובחרו בחברה של 'האיש עם השפם' (הוא דניאל, בדיחה פנימית). זה היה קיץ 2025, לפני Opus 4.5 ולפני Spec Kit (ספטמבר). המסר: 'עם AI, דברים רעים נהיים גרועים ודברים טובים נהיים טובים יותר'."],"points":[],"kind":"idea"},{"title":"שלב 1: Discovery לפני אימון","body":["הם הדגישו שהדגש אינו מכירתי אלא איך לעשות זאת בארגון שלכם. דוח DORA 2025 (כפי שציטטו, ללא אימות) טען שכשפיתוח לא טוב, הוספת קידוד סוכני מחמירה: מאיצים חלק אחד ומחשפים צווארי בקבוק. בארגון טוב זה מאיץ אקספוננציאלית. אף אחד לא יודע איפה נקודת האיזון.","מה בדקו: CI/CD ופלטפורמה (בלי פלטפורמה אי אפשר לשלוח קוד מהר ובאמינות), בדיקות (אם סוכנים לא יכולים להריץ בדיקות, 'אל תתפלאו שהם שוברים'), סטנדרטים משותפים (אם בני אדם לא מסכימים מה זה טוב, סוכן לא יפיק קוד שהצוות יאשר). בבקשה (RFP) כבר כתבו שישלמו על שלב גילוי."],"points":[],"kind":"idea"},{"title":"שלב 2: סדנאות אנושיות בפיזית","body":["בהכשרה הראשונית הם אספו אנשים במשרד (המשרד הישן של Spotify בשטוקהולם). הם השתמשו ב-Liberating Structures (תבניות לשיחה שמונעות שליטה של קולות חזקים) כדי לשאול מה אנשים מרגישים, האם הם חוששים לשביעות רצון או למוטיבציה.","בתרגיל TRIZ שאלו: 'דמיינו ש-Odevo מעסיקה 200 מפתחים זוטרים מתרבות שבה תמיד אומרים כן, לא מתווכחים ולא ישנים, עם Red Bull ברידיד. איך נגרום לאסון הגדול ביותר?'. התשובות חשפו שהבדיקות לא מספיק טובות בכל הצוותים ('אתם גם? גם אנחנו'). זה הפחית התנגדות וחשש. הם גם הריצו פיילוט ב-11 בנובמבר ואז הגיעה הקבוצה הגדולה של 80 איש."],"points":[],"kind":"idea"},{"title":"טכניקות הוראה ותוכנית הלימודים","body":["אחרי כל תרגיל שואלים 'מה בדיוק עשינו עכשיו?' ומציירים בזמן אמת: התקנתם Claude, מאיפה, הפרומפט לאן הלך, איפה הכלים רצים, איך המודל בוחר כלי. זה יוצר נוכחות חברתית וייצוג חזותי ומקבע ידע. בחצי הראשון של היום ללא מחשבים ניידים, ועם אוכל לכולם (לפי הדוברים, חשוב בשוודיה).","מודולים: ניהול הקשר וחלון הקשר יעיל (ככל שמוסיפים יותר הקשר המודל יוצא מהפסים). הם ציינו שמחקרים אקדמיים מראים שעדיף ללא הוראות ב-AGENTS.md מאשר הרבה. תרגילים עם מודלים ישנים שקל לגרום להם להזות, כדי להראות כשלים ולא רק 'נתיב שמח'. מעבר מ-VS Code ו-Copilot אל Claude Code בטרמינל הוא קפיצה פסיכולוגית כי הסוכן בוחר מה להציג. אחר כך MCP, Spec-driven, וזרימות Multi-agent (Gastown / Gas City).","האימון לא היה מיום אחד: מודולים שבועיים של חצי יום ו'שיעורי בית' על הקוד האמיתי. הם ממליצים להכין את IT לכך שאנשים יתקינו תוכנה (איבדו 15 עד 30 דקות כי אי אפשר היה להתקין Docker)."],"points":[],"kind":"idea"},{"title":"התוצאות כפי שדווחו","body":["אחד הצוותים חשב מחדש את תהליך האספקה: שבועיים של דיבור על דרישות (עם תמלול אוטומטי), סוכנים מייצרים PRD, מודל ישויות ותוכנית משימות, ומפתחים לוקחים כמה Epics ביום, עושים 7 עד 8 סבבי code review עצמי ומבצעים self-merge, ללא סקירה אנושית. הם משתמשים בצוות כ'מגדלור'."],"points":["קבוצת הליבה של המפתחים הוכשרה עד אמצע פברואר (לפי התמלול).","אימוץ AI כ-94% (מי ששימש ב-AI לפחות בחלק מתוך 10 העבודות האחרונות); 50 עד 60% ב-10 מתוך 10; רק 6% לא משתמשים, והם עושים איתם ראיונות.","זמן לשוק קצר יותר, גידול מתמשך בתפוקת PR, ולוחות מחוונים שקופים לכל המפתחים.","המדד החשוב לדעתם: 'נועזות' (boldness): כמה ניסויים נועזים עושים.","שכתוב פלטפורמה שנבנתה שמונה שנים בידי כ-20 מפתחים: שכתוב 1 ל-1 תוך שלושה שבועות; כעת צוות של ארבעה. ניסיון לבנות אפליקציית מובייל בשלושה ימים לא הצליח."],"kind":"idea"},{"title":"אנשים: ספקנים, DX וצוות מדריכים","body":["דום היה ספקן (חששות אתיים, אנרגיה, חוויה קודמת עם ChatGPT). כשקיבל אפשרות לשחק עם Opus 4.5 בנובמבר שינה דעה. הוא לא כתב קוד בעבודה 4 עד 5 חודשים וכותב בבית כתחביב, כמו נגרות אחרי קניית רהיטים. דניאל, מצוות חוויית המפתח, בנה כלי טלמטריה בלי לכתוב קוד, ולפי דבריו שיפר ביצועים בהרבה. ניקולס, מפתח חזק, הפך למדריך, ומדריך פנימי עם ניסיון אמיתי משכנע יותר.","הדוברים מזהירים: מוצר ועיצוב הופכים לצוואר הבקבוק הבא, ולכן מתאימים את האימון גם להם, ובהמשך ללמד 13,000 עובדים שימוש בסיסי (רואי חשבון כבר בונים אפליקציות קטנות)."],"points":[],"kind":"idea"},{"title":"הצד האפל והחזון","body":["כמה מהנדסים אומרים 'אני לא מצליח להפסיק', גם בשש, שבע או בלילה, והם מדברים על דחף דופמין וקופסאות סקינר. הם מזכירים מחקר (של Lauren Peate, מנכ\"לית Multitudes) שלפיו ארגונים מקבלים שעות נוספות בגלל לחץ תפוקה אחרי אימוץ. בעבר זה לא קרה אצלם.","החזון: כל עובד ב-Odevo הוא בונה. מנקודת מבט היסטורית: פעם בעלי עסק יצרו טפסים בעצמם, אחר כך הכול הועבר למפתחים, וכעת חוזרים ליכולת של משתמשי עסק. לא פחות מפתחים, אלא יותר תוכנה מותאמת אישית במקום 'תוכנה גדולה ואיטית'."],"points":[],"kind":"idea"},{"title":"מה נשאר מהסשן","body":[],"points":["בלי יסודות (פלטפורמה, בדיקות, סטנדרטים) הוספת סוכנים מחמירה את המצב.","אימון בפיזית עם דגש על כשלים, ולא רק על 'נתיב שמח', וליווי בעבודה על קוד אמיתי.","המדד החשוב הוא נועזות; הצד האנושי כולל גם התמכרות ולחץ."],"kind":"idea"}],"diagram":{"kind":"timeline","title":"מסלול הטרנספורמציה ב-Odevo (כפי שסופר)","nodes":[{"id":"a","label":"2024: Copilot ~30%, שיטות עבודה ושקיפות"},{"id":"b","label":"קיץ 2025: RFP ובחירת שותף"},{"id":"c","label":"Discovery: CI/CD, בדיקות, סטנדרטים"},{"id":"d","label":"סדנאות בפיזית + פיילוט 11 בנובמבר + קבוצה של 80"},{"id":"e","label":"מודולים שבועיים ושיעורי בית"},{"id":"f","label":"אחרי האימון: 94% אימוץ, שכתוב בשלושה שבועות"},{"id":"g","label":"הבא: מוצר, עיצוב וכל העובדים"}],"edges":[{"from":"a","to":"b","label":""},{"from":"b","to":"c","label":""},{"from":"c","to":"d","label":""},{"from":"d","to":"e","label":""},{"from":"e","to":"f","label":""},{"from":"f","to":"g","label":""}],"caption":"סדר הזמנים לפי דברי הדוברים; חלק מהתאריכים נאמרו בקירוב."},"terms":[{"term":"Discovery","definition":"שלב בו יועץ בוחן את מצב הארגון (CI/CD, בדיקות, סטנדרטים) לפני הכנסת כלי AI."},{"term":"Liberating Structures","definition":"תבניות לניהול שיחות שמפחיתות שליטה של קולות חזקים."},{"term":"Boldness","definition":"המדד שהציעו להצלחת טרנספורמציית AI: כמה דברים נועזים ומנסים."}],"gaps":["התמלול לא כולל שאלות וקהל: המנחה עצר את הסשן לפני צהריים.","תאריך סיום האימון: בתמלול נאמר 'אחרי שסיימנו בפברואר' ובהמשך 'עד אמצע פברואר'; אין פירוט מעבר לכך.","נתון שיפור ביצועים של דניאל מתומלל לא ברור ('2000 30s').","כל המספרים (94%, 2.5 מיליון בתים, שכתוב בשלושה שבועות, 20 מול 4 מפתחים, '2000 אחוז') הם של הדוברים בלבד ולא אומתו.","הטענות על DORA ועל מחקרים בנושא AGENTS.md הן ציטוט של הדוברים ולא נבדקו."],"source_refs":["https://www.youtube.com/watch?v=mB74LGAmmV0"]},{"number":21,"id":"AHIY1XccX_E","url":"https://www.youtube.com/watch?v=AHIY1XccX_E","type":"session","type_he":"סשן","duration":"31:32 דקות","title_he":"cq: מאגר פתרונות משותף לסוכנים","speaker_he":"פיטר וילסון ודוידה איינארד","summary":"פיטר וילסון ודוידה איינארד מ-Mozilla.ai מציגים את cq: פרויקט קוד פתוח שמאפשר לסוכן לשמור 'יחידות ידע' (knowledge units) כשהוא פותר בעיה לא טריוויאלית, ולסוכנים אחרים לשלוף אותן, מקומית, בצוות או בקהילה.","takeaways":["יחידת ידע מתארת בעיה לא מובנת מאליה, פתרון והקשר כגון שפה ומסגרת. אפשר לחפש, להציע ידע, לאשר שעבד או לסמן שגיאה.","ברירת המחדל היא SQLite מקומי שאינו שולח ידע החוצה. חיבור לשרת מרוחק הוא צעד נפרד ושיתוף מרוחק דורש ביקורת אנושית.","Skill מכוון לחיפוש בתחילת משימה ולאימות התאמה לפני יישום. Reflect יזום בסוף סשן מאפשר לערוך מה ראוי לשמר.","בדמו, התקנת שרת MCP נכשלה בגלל מיקום קובץ תצורה. אחרי בדיקת התיעוד ושמירת פתרון, ניסיון חדש נמנע מהטעות.","ידע יכול להכיל מידע אישי, הוראות מזיקות או פתרון לא מתאים. בדיקות תוכן, הרשאות, אימות וביקורת הן שכבות הגנה בלבד.","הפעלה ושליפה לפי תחום דורשות שיפור. חתימות, קידום ידע למאגר ציבורי ופדרציה מוצגים בחלקם כמפת דרכים, לא כמימוש שהושלם."],"category":"הקשר וזיכרון","coverage":"כל התמליל הזמין נסקר. בטקסט שסופק מופיעים גוף ההרצאה, הסיכום ושאלות מהקהל. אין כאן אימות מול הווידאו או הוכחה שלא חסרו קטעים באמצע. Stack Overflow לסוכנים הוא דימוי, לא שירות Stack Overflow. יש להבדיל בין יכולות קיימות לבין מפת דרכים.","source_basis":"תמלול מלא שסופק (קובץ מקור 4, פריט 1), כולל שאלה אחת. הקובץ המקביל בחבילת הטקסט הרשמית קצר מאוד (כ-2.8KB) ולא שימש כמקור מלא.","lead":"סוכנים שלומדים פתרונות לבעיות שלא ראו ומשתפים אותם כ'יחידות ידע' עם סקירה אנושית","chapters":[{"title":"Mozilla.ai ומשימת הקוד הפתוח","body":["דוידה פותח בכך ש-Mozilla.ai אינה 'אנשי Firefox' אלא צוות שמקדם בינה מלאכותית בקוד פתוח, נפרד מתאגיד Mozilla. התרגיל שהוא משאיר לקהל: לפתוח את ה-Manifesto של Mozilla ולהחליף 'האינטרנט' ב-'AI' ולבדוק אם העקרונות עדיין נכונים.","הוא טוען שההשוואה בין מודלים פתוחים לשירותי AI מסחריים לא הוגנת: שירות מסחרי הוא לא רק LLM אלא סוכן, קוד, כלים והנדסה של אלפי מהנדסים. המשימה היא לצמצם את הפער בחוויה."],"points":[],"kind":"idea"},{"title":"הקשר: דוגמה שלילית וחיובית","body":["שלילי: כלי 'agents' בדפדפן שמתחבר ל-LLM מקומי. הוא ביקש לבדוק כמה כוכבים יש לפרויקט any-agent ובתגובה קיבל את המדריך של הפרויקט. הסיבה: גודל ההקשר הדיפולטי היה 4K, והכלי הוריד מהרשת הרבה יותר טוקנים, ההקשר נחתך, המודל שכח את השאלה וסיכם את הדף. הלוגים לא היו נראים למשתמש.","חיובי: שאלה על יום ההולדת. Claude בלי כלים אומר שאינו יודע. כשנתנו למודל מקומי קטן (0.8 מיליארד, הוא מציין שהיו צריכים כמה ניסיונות) כלי של שתי פונקציות (לעבור על תיקייה ולקרוא קובץ) הוא פתח קובץ birthdays ועונה נכון. המסקנה: הקשר נכון יכול לגרום גם למודל קטן לעבוד טוב."],"points":[],"kind":"idea"},{"title":"החוסר: פתרונות שהמודל עוד לא חווה","body":["כשסוכן נתקל בבעיה שלא מוכרת לו, הוא ינסה פתרונות עד שמישהו יתערב ויאמר 'עשה כך'. מה אם אפשר לשמור את זה וללמוד? Claude כבר יש לו זיכרונות, אבל פיטר מסביר למה זה לא מספיק.","הבעיות שלו: הכול נשמר מקומית, בקובץ CLAUDE.md גלובלי ופרויקטלי שנטען להקשר (ולכן ספק המודל רואה אותו), ולפעמים הסוכן 'שוכח'. הוא מספר שביקש מ-Claude לבדוק כפילויות בין קבצי הזיכרון; הסוכן ענה שאין כפילות כי הקבצים לא זהים בבייטים ובשם. רק אחרי הכוונה לבדוק את הכוונה הוא גילה שכתב אותו זיכרון שוב ושוב בלי להשתמש בו. הוא מתאר זאת כ'סשן טיפול'."],"points":[],"kind":"idea"},{"title":"מה זה cq ומה זו יחידת ידע","body":["הפוסט הראשון תיאר את cq כ'Stack Overflow לסוכנים'. כשסוכן נתקל בשגיאות ומוצא פתרון, הוא אמור להציע 'יחידת ידע' ל-cq. יחידת ידע נשמרת כ-JSON (בשקף כ-YAML): התחומים (domains), התובנה, הפעולה שננקטה, ומטא-דאטה כמו שפות, פריימוורקים ודפוס.","יש cq Exchange מתארח, וגם שרת קוד פתוח שאפשר להריץ ב-Docker. הדוברים מזכירים שאין מדובר בשמירת הסשנים עצמם."],"points":[],"kind":"idea"},{"title":"איך זה עובד: Skill, MCP, אימות וציון אמון","body":["יש Skill שמתקינים כתוסף, שמפעיל שרת MCP. לפני התחלת משימה חדשה ה-Skill מורה לסוכן לשאול את cq על התחום ולקבל מידע ממוקד, לא להעמיס הכול מראש. הסוכן יכול להציע (propose), לאשר (confirm) יחידה שעבדה, או לסמן (flag) יחידה שגויה, כך שנבנה ציון ביטחון עם הזמן. ההנחיה: לאמת את ההצעה לפני הפעלתה, לא להסתמך בעיוורון.","יש גם טריגר אנושי: בסוף סשן אפשר לבקש מהסוכן 'להרהר' על כל הסשן, להציע יחידות ידע, ולאשר או לערוך אותן."],"points":[],"kind":"idea"},{"title":"שלוש רמות פריסה","body":["מקומי: ברירת מחדל היא מסד SQLite מקומי, שום דבר לא יוצא מהמכונה, אין סקירה וכל הסוכנים במכונה רואים הכול מיד. צוות: מתחברים לשרת מרוחק (קוד פתוח) עם משתמשים וסיסמאות, והצעות עוברות תהליך סקירה (שהם מתארים בבדיחה כ'דומה לטינדר'; בשקף מסך עם החלקה ימינה ושמאלה בשרת הפתוח). Commons ציבורי: ברמה של Mozilla (מנוהל) שבה אפשר 'לבחור' יחידה מהמרחב הפרטי להעלאה לציבורי, בדומה לתצוגת Stack Overflow."],"points":[],"kind":"idea"},{"title":"הדגמה אישית: Joplin MCP","body":["דוידה רצה לחבר את Joplin (כלי רשימות קוד פתוח בו הוא משתמש כ-15 שנה) כ-MCP ל-Claude כדי לקבל חוויית 'LLM wiki'. בתחילת אפריל Claude הוסיף שרת MCP והצהיר שהכול בסדר, אבל אחרי הפעלה מחדש השרת לא נמצא. הסוכן המשיך לחפש סיבות זמן רב. רק אחרי הצעה לבדוק את התיעוד העדכני באתר, מצא שקובץ ההגדרות צריך להיות בנתיב אחר ותיקן.","אחר כך הוא ביקש מהסוכן 'לשקף': לעבור על ה-trace ולכתוב יחידת ידע. היא נשמרה מקומית. הוא מחק הכול והתחיל מחדש, ו-Claude Code חיפש אוטומטית ב-cq, מצא את הפתרון והשתמש מיד בקובץ ההגדרות הנכון. הוא מדגיש: 'לא תיקנו את זה לכולם או לתמיד', רק למקרה האישי ולמכונה המקומית."],"points":[],"kind":"idea"},{"title":"סיכונים והפחתות","body":["הדוברים מודים: זה דומה לרשת חברתית ויש סיכונים. יחידת ידע עלולה להכיל הוראות מזיקות או מידע אישי. התקפות שרת: DDoS וזיוף זהות. הם התייעצו עם מומחה אבטחה, ביצעו ניתוח STRIDE פנימי, והוסיפו ל-Skill בדיקת 'ויב' מקדימה שמסננת תכנים, והפרוטוקול מורה תמיד לאמת לפני פעולה.","בהמשך מתוכננים: חתימה קריפטוגרפית של יחידות ידע (העלאת מפתח ציבורי), מפתחות API קצרי חיים שמואצלים לסוכן (בלי פעולות control plane), צינור guardrails (בדיקות PII, sandbox), וסקירה אנושית 'in the loop' שמטרתה בהמשך להפוך ל-'on the loop' כדי להתרחב. כרגע נשארים עם סקירה אנושית."],"points":[],"kind":"idea"},{"title":"מה למדו ומה בהמשך","body":"","points":["הפעלת ה-Skill בזמן הנכון היא 'מאבק על תשומת הלב': הם בחרו לא להשתמש ב-hooks ולנסות לגרום לסוכן לדעת מתי לפעול (בתחילת משימה ולא לפני כל קריאה). גם גרסאות Skills קשות.","פרטיות כברירת מחדל: אי אפשר לראות מי יצר מפתח; הכול opt-in. מחיר: איטי יותר להגיע לפיצ'רים.","זה מצטבר: גם בשימוש לא מקוון זה נעשה שימושי כשיותר נמצא. דוגמה: סוכן שכותב GitHub Actions משתמש בגרסאות ישנות, ובלי cq ממשיך לעשות זאת ב'דנינג-קרוגר מלא'.","פלטפורמה לפני פרוטוקול: אולי צריך פלטפורמה ראשונה כדי לדעת מה להכניס לסכמה.","מפת דרכים: מרחבי שמות (tenancy) לארגונים, צינור 'מועמדות והעלאה' מפרטי לציבורי, חתימה, ייצוא לסכמה פתוחה, ופדרציה בין שרתים (שוחחו עם גופים על קבוצת עבודה)."],"kind":"idea"},{"title":"סיום: דרכי השתתפות","body":["דוידה משתמש בתמונה מפרסום משנת 2006 על חוק החזקה של השתתפות: מהמאמץ הנמוך ועד הגבוה. ההמלצה: לנסות את האתר, לשכפל את ה-repo, לפתוח issues (הם מבקשים ביקורת קשה), ולתרום. הוא מזכיר 'choice-first stack' של פרויקטי Mozilla.ai הפתוחים: פריימוורקים לסוכנים, ניתוב, הגשת מודלים מקומית, guardrails ועוד. השאיפה: פרויקט פתוח שמנצח, וידע משותף שאינו בבעלות חברה אחת."],"points":[],"kind":"idea"},{"title":"בארגון גדול עם הרבה מאגרים ותחומים, איך השליפה עובדת ואיך נמנעים מדליפת מידע שגוי?","body":"ה-Skill מנחה את הסוכן לסכם, לקבוע תחומים ולהכליל ולא להתאים לפרויקט ספציפי (אלא אם זה כלי קוד פתוח). יש רשימת תחומים, שפות, פריימוורקים ודפוס חופשי. בהצעה מרחוק פועלים guardrails וסקירה אנושית. דוידה מוסיף שזו בעיית שליפה, והמימוש הראשון ישתפר. יש PR פתוח להוספת חיפוש סמנטי.","kind":"qa"},{"title":"מה נשאר מהסשן","body":[],"points":["הקשר נכון מרים גם מודלים קטנים; ידע שנלמד בסשן צריך להישמר ולהיות משותף.","שיתוף ידע בין סוכנים מחייב אימות, פרטיות, אבטחה וסקירה אנושית.","הפרויקט מצהיר שהוא בשלבי בנייה (פברואר עד יוני 2026) ושחלק מהפיצ'רים בתכנון."],"kind":"idea"}],"diagram":{"kind":"tiers","title":"שלוש רמות שיתוף של יחידות ידע ב-cq","nodes":[{"id":"l","label":"מקומי: SQLite במכונה, בלי סקירה"},{"id":"t","label":"צוות: שרת קוד פתוח, משתמשים, סקירה אנושית"},{"id":"c","label":"Commons: מנוהל (Mozilla), בחירה וקידום מרחב פרטי"}],"edges":[{"from":"l","to":"t","label":"חיבור לשרת מרוחק"},{"from":"t","to":"c","label":"מועמדות והעלאה"}],"caption":"הסוכן שואל ויחידות עוברות אימות וציון אמון בכל רמה."},"terms":[{"term":"Knowledge unit","definition":"רשומה מובנית (JSON/YAML) על בעיה ופתרון: תחומים, תובנה, פעולה, מטא-דאטה."},{"term":"cq Exchange","definition":"גרסה מתארחת של cq עם מרחבי שמות ותהליך קידום."},{"term":"Commons","definition":"שכבה ציבורית מנוהלת של יחידות ידע מאושרות."},{"term":"Human in the loop / on the loop","definition":"סקירה אנושית לכל פריט, לעומת פיקוח עקיף כדי להתרחב."}],"gaps":["התמלול מאבד חלקים ('Tesla vibes', 'skeletal frames') ולא ברור מה התכוונו.","גרסת התמלול הרשמית בחבילה קצרה מדי (כ-2.8KB) ולכן לא נבדקה מולה.","בתמלול אין מספרים על היקף ה-Commons או מדד אמון.","הטענה ש-Claude 'בודק בייטים זהים' וההתנהגות של הסוכן הן חוויית הדוברים ולא בדיקה עצמאית."],"source_refs":["https://www.youtube.com/watch?v=AHIY1XccX_E"]},{"number":22,"id":"6VRKZQ3pmoU","url":"https://www.youtube.com/watch?v=6VRKZQ3pmoU","type":"session","type_he":"סשן","duration":"32:39 דקות","title_he":"ממיומנויות אישיות לתהליך צוותי מנוהל","speaker_he":"ג׳יימס מוס","summary":"ג'יימס מוס, Member of Technical Staff ב-Tessl (עובד על מוצר ה-Registry), מסביר איך ארגונים מתמודדים עם Skills כשמעבר מפרויקט אישי לצוות: התפשטות (sprawl), עקרונות כתיבה, נקודות בקרה, ומשל מ-2005 על חבילות ב-PHP.","takeaways":["למפות חפיפה, סטייה בין גרסאות, אי-הפעלה, התיישנות ועומס הקשר. יותר Skills אינם בהכרח יותר יכולת אם תיאורי ההפעלה נחתכים.","לפרק Skills גדולים לאחריויות ממוקדות. להרחיב Skill צד שלישי בשכבה פנימית במקום לערוך עותק שמתנתק מהמקור.","כל Skill שמשנה פלט צוותי צריך להיות מנוהל לצד הפרויקט, לא הגדרה נסתרת במחשב מפתח שגורמת להתנהגות שונה ללא עקבות.","לשלב סקירות מהירות ב-CI והערכות משימתיות. לבדוק גם אם מודל השתפר עד שה-Skill אינו נחוץ.","רישום מרכזי מאפשר גרסאות נעולות, דיפים, חזרה לאחור ומדיניות אבטחה. גיל מינימלי לגרסה מסייע לצמצם סיכון של עדכון זדוני חדש.","לשמור ניידות בין כלים ובעלות משותפת. הפצה ללא-טכניים וייצוג תלויות בין Skills מתוארים כשאלות שטרם קיבלו תשובה טובה."],"category":"הקשר וזיכרון","coverage":"כל התמליל הזמין נסקר. בטקסט שסופק מופיעים גוף ההרצאה, הסיכום ושאלות מהקהל. אין כאן אימות מול הווידאו או הוכחה שלא חסרו קטעים באמצע. מלאי ה-Skills של Tessl מתואר כבטא פרטית בזמן הכנס. טענות חיסכון ודיוק מרשתות חברתיות מוצגות כביקורת על טענות לא מבוססות, לא כתוצאות שהדובר מאמץ.","source_basis":"תמלול מלא שסופק (קובץ מקור 4, פריט 2), כולל פתיחת המנחה וחמש שאלות. תמלול אוטומטי עם שגיאות שמות (Snyk מתומלל 'sneak').","lead":"מנהלים Skills כמו תוכנה: סקירה, רישום, בקרת גרסאות, מדידה ו-evals","chapters":[{"title":"Skill sprawl: הפיצוץ הקמבריוני","body":["Skills הם בעיקר קובצי טקסט (לפעמים עם סקריפטים), קל לכתוב ולהתקין מ-GitHub, וחזקים. מכאן 'פיצוץ קמבריוני': הוא מזכיר (דברי הדובר בקונטקסט של הרצאת הפתיחה) מעל 2 מיליון Skills ציבוריים ב-44,000 מאגרים. Skills מתפזרים ב-GitHub, ב-Claude Marketplaces ובמכונות מקומיות, וללא ראות אי אפשר למדוד ולשפר.","הוא מציג ציטוטים מלקוחות: 'אי אפשר לאחד ולהפיץ Skills בין צוותים', 'זה Wild West', וביקש מהקהל הרמת ידיים: רבים אין להם תמונה ברורה של כל ה-Skills בשימוש."],"points":[],"kind":"idea"},{"title":"חמישה כשלים של sprawl","body":["בתגובה Tessl בנתה Skills Observatory שמתחבר לארגון GitHub, אוסף Skills מכל המאגרים, ומציג פירוט לפי מאגר, Skill, צד ראשון או שלישי, שימוש בטוקנים וממצאים של הכשלים הללו, וגם ביקורות וציוני eval וסריקות אבטחה מה-Registry הציבורי. זה בבטא פרטית."],"points":["Overlap: צוותים שונים בונים אותו Skill בנפרד.","Drift: גרסאות חדשות לא מאומצות. דוגמה: Matt Pocock פרסם גרסה חדשה של 'grill me' בשם 'grill with docs', וחלק ממשיכים עם הישנה.","Activation: לא יודעים אם Skill מופעל על ידי סוכנים או בני אדם.","Out-of-sync: Skill שמתאר קוד או תהליך שהשתנה; Skill מיושן עלול להיות גרוע כמו היעדרו.","Overloading: יש מגבלה (באחוז מחלון ההקשר) על התיאורים של Skills שנטענים בתחילת ההקשר. סוכנים רבים קוצצים תיאורים, ולכן Skill עלול לא להיות מופעל."],"kind":"idea"},{"title":"משוואת הסוכן ולמה Skills","body":["הוא מגדיר: סוכן = פונקציה של מודל, harness והקשר. לרוב לא משנים את המודל או ה-harness, ולכן הקשר הוא הידית החזקה. Skills מקודדים לוגיקה עסקית או תחומית שהמודל לא אומן עליה."],"points":[],"kind":"idea"},{"title":"עקרונות כתיבה ופעולה","body":["על גיל מינימלי: לפני 3 עד 4 שבועות, לדבריו, התפשטה בהתקפת שרשרת אספקה על חבילות npm (בתמלול 'mini Shiloh') שהוסיפה hook גלובלי ל-Claude Code כדי להתמיד. אצלם לא נפגעו כי למנהל החבילות יש גיל מינימלי של כמה ימים. הוא מוסיף, מדברי המרצה בבוקר, שכ-20% מה-Skills ב-OpenClaw (לפי דבריו) זדוניים."],"points":["פרקו ל-Skills קטנים (decompose): תיאור לכל חלק מגדיל סיכוי הפעלה נפרדת. הוא מזכיר Plugins כקבוצת הקשר שמותקנת יחד. דוגמה: מ-Figma ל-UI: Skill אחד מפרק עיצוב לרכיבים ומעביר ל-Skills אחרים (רכיבים נמוכים כמו כפתור, בינוניים כמו טפסים, גבוהים כמו עמודים), וגם אפשר להפעיל ידנית רק את הנמוך.","הרחיבו (extend) ולא ערכו ישירות Skills של צד שלישי: כתבו Skill ראשון שמפעיל את הצד השלישי ומתאים לסטאק שלכם. עיקרון אחריות יחידה (SRP).","הימנעו מ-Skills גלובליים (בעיית 'עובד אצלי'): Skill שמותקן מחוץ למאגר גורם להתנהגות תלוית מי מריץ, בלי עקבות ב-diff, בסקירה או ב-CI. הוא מצטט (מפי עמית שהיה בפורום) את Boris Cherny: 'אנחנו אוסרים כל סט-אפ מקומי; שיפורי סוכן, hooks, Skills נכנסים למאגר'.","סקירה אוטומטית של Skills כמו linter: מהירה, מקומית ובצנרת CI עם שער איכות. בדוגמה Skill שלו קיבל סימוני תקין אבל שופט LLM נתן 20% כי הכיל 'פעולות כספיות מסוכנות', ולכן לא היה מפורסם.","פרסמו ל-Registry: מקור אמת אחד וגרסה נעוצה; מניעת forks מבלבלים; עדכון בטוח עם diffs ו-rollback; גילוי למניעת overlap; וחסכון ברישיונות GitHub למשתמשים לא טכניים. Registry הוא גם נקודת אכיפה: Skills מאושרים בלבד, סריקות אבטחה (אצלם בשותפות עם Snyk, כך נראה), וגיל מינימלי לגרסה.","אל תנעלו את Skills לסוכן אחד. בשקף: רשימת נתיבי פרויקט רבים. הסוכנים יחליפו, ו-Skills הם הנכס העמיד והסוכן רק זמן ריצה. מנהל חבילות יכול להתקין לכל סוכן.","הפכו הקשר לנכס צוותי: DRY, בעלות משותפת, ו'בטוח לתרום' עם CI ושערים."],"kind":"idea"},{"title":"מדידה עם evals","body":["הוא מצטט פוסטים 'מרשימים': Skill שחותך 60 עד 80% מהטוקנים, 'ארבעה כללים' שמעלים דיוק מ-65 ל-94%, 'פרומפט קסם' שמוסיף 20,000 טוקנים ומבטל 90% מהבאגים. הוא מצטט את אדם סאבאג': 'ההבדל בין לשחק לבין מדע הוא לרשום'.","evals מאפשרים לשנות כל חלק במשוואה (מודל, harness, הקשר) ולמדוד פלט, על Skill אחד או כמה, על בסיס קוד אמיתי. הם עונים: האם השינוי מחמיר? האם Skill עובד עם מודלים אחרים? האם עדיין צריך את ה-Skill כי המודל השתפר?"],"points":[],"kind":"idea"},{"title":"Context Development Lifecycle","body":["כל מה שעושים לבריאות הקוד יש לו מקבילה להקשר: סקירת Skills כמו linting ו-unit tests, evals כמו בדיקות end-to-end, Registry כמו רישום קוד, קומפוזיציה ו'בלי מצב גלובלי', ושיתוף ידע נגד bus factor.","המשל: ב-2005 הוא כתב PHP בעבודה הראשונה, בלי מנהל חבילות (Composer הגיע 7 שנים אחר כך). הורידו ZIP מ-SourceForge, בלי סקירת אבטחה, בלי semantic versioning, ופרסו ב-FTP (לפחות SFTP). לוקח לתעשייה כעשר שנים לתקן. 'כעת אנחנו עושים זאת שוב עם Skills והקשר: מדלגים על מנהלי חבילות ועל CI'. אבל 'אנחנו כבר יודעים איך הסיפור נגמר' ואפשר ליישם SDLC על CDLC."],"points":[],"kind":"idea"},{"title":"האם צריך לארוז כמה Skills ל-Plugin או לשמור נפרד?","body":"'זה תלוי'. Tessl מתכננת לאפשר העלאת Skills בודדים, אבל מתמקדת ב-Plugins כעת. אפשר לארוז Skills קשורים, וגם Plugins רחבים כ'ספריית סטנדרט' ארגונית.","kind":"qa"},{"title":"איך משתפים Skills עם אנשים לא טכניים (למשל עדכון JIRA)?","body":"זו בעיה גדולה והוא אומר שאין תשובה טובה. לצפות מאנשים להריץ CLI קשה, והוא מדמיין GUI אך לא מתחייב.","kind":"qa"},{"title":"מה דעתך על APM?","body":"זה מנהל חבילות (התחיל אצל מפתח במיקרוסופט ועבר ל-Microsoft), הוא ניסה, טוב, ואם מתאים כדאי להשתמש.","kind":"qa"},{"title":"איך להביע תלויות בין Skills בחבילות שונות?","body":"אין תקן. אפשר לחשוב על peer dependencies, אבל כולם חוששים לגעת בזה. אולי עולם הסוכנים מאפשר לסוכן לקרוא Skill ולהחליט שהוא צריך Skill אחר.","kind":"qa"},{"title":"מה נשאר מהסשן","body":[],"points":["למדוד שימוש ב-Skills ולעקוב אחרי שינויים.","לנהל Skills בגרסאות במאגר, לסקור אוטומטית, לפרסם ל-Registry עם מדיניות, ולמדוד עם evals.","להשתמש בלקחי SDLC ולא לחכות עשר שנים."],"kind":"idea"}],"diagram":{"kind":"mapping","title":"מקבילות בין SDLC להקשר (CDLC)","nodes":[{"id":"l","label":"linting + unit tests  ←→  Skill review"},{"id":"e","label":"בדיקות end-to-end  ←→  evals"},{"id":"r","label":"package registry  ←→  context registry"},{"id":"g","label":"בלי מצב גלובלי  ←→  Skills במאגר, לא בבית המשתמש"},{"id":"b","label":"bus factor  ←→  בעלות משותפת וסביבה בטוחה לתרומה"}],"edges":[{"from":"l","to":"e","label":""},{"from":"e","to":"r","label":""},{"from":"r","to":"g","label":""},{"from":"g","to":"b","label":""}],"caption":"בחירת הכותב על פי הדוגמאות שהדובר הביא; הדובר לא הציג את זה כרשימה אחת."},"terms":[{"term":"Skill sprawl","definition":"התפשטות בלתי מבוקרת של Skills בארגון, בכמה מקומות וגרסאות."},{"term":"Agent equation","definition":"סוכן = מודל + harness + הקשר."},{"term":"Skill registry","definition":"מקור אמת מרכזי לגרסאות Skills עם גילוי, מדיניות וסריקות."},{"term":"CDLC","definition":"Context Development Lifecycle: מקבילה לתהליך פיתוח תוכנה עבור הקשר."},{"term":"Minimum release age","definition":"כלל שמונע התקנת חבילה שפורסמה לפני פחות מכמה ימים."}],"gaps":["המוצר Skills Observatory מוצג כבטא פרטית; אין פרטים נוספים מעבר לדברי הדובר.","ציטוט Boris Cherny מגיע דרך עמית (עדות שנייה).","שם התקיפה ב-npm מתומלל 'mini Shiloh' ואינו אומת.","הנתונים על 2 מיליון Skills, 44,000 מאגרים, 20% זדוניים, התקפת npm והדוגמאות לפוסטים הם של הדובר ולא נבדקו.","Tessl היא מעסיק הדובר, והוא מציג את המוצר שלה (Observatory/Registry)."],"source_refs":["https://www.youtube.com/watch?v=6VRKZQ3pmoU"]},{"number":23,"id":"gc5_ICZg9tg","url":"https://www.youtube.com/watch?v=gc5_ICZg9tg","type":"session","type_he":"סשן","duration":"35:18 דקות","title_he":"אבטחת קוד בעידן AI: מגילוי אמין לתיקון שימושי","speaker_he":"ג׳וזף קציולודס","summary":"ג'וזף קציולודס, Senior Developer Advocate ב-GitHub וחבר ב-GitHub Security Lab, מראה שימושים מעשיים ב-AI לאבטחה: כתיבת קוד בטוח, MCP ו-Skills, תיקונים ב-PR, Agentic Workflows, Taskflows, החלטות שרשרת אספקה, fuzzing ומגרש משחקים לתקיפת צ'אטבוט. הוא מדגיש שהכול אפשרי גם ב-Claude Code ו-Codex ולא רק ב-Copilot.","takeaways":["להפריד גילוי מהסקה: סריקה מוכרת מספקת ממצאים והסוכן מסביר הקשר ומציע תיקון. מספר תשובות אינו מדד דיוק אם יש ממצאי שווא והחמצות.","MCP נותן גישה לתוצאות ומידע; Skill מגדיר טריאז׳ ותיקון. בלי תהליך יש יכולת ללא מתודולוגיה, ובלי כלים יש הוראות ללא ביצוע.","להביא הסבר ותיקון ל-PR עם בדיקות וביקורת, במקום להעביר מפתחים בין לוחות בקרה. מוקד ההרצאה הוא קצב תיקון ולא עוד ערוץ גילוי.","תהליכים מותאמים בוחנים סיכונים התנהגותיים ושאלות מערכתיות שסריקה לבדה מתקשה להסיק. לצמצם היקף ולא להעמיס כל כלל על הוראה אחת.","AI יכול לסייע בבדיקת תלות ויצירת קלטי Fuzzing וסביבת הרצה. לבסס מסקנות על מקורות ובדיקה בפועל, לא על הבטחת מודל.","שופט LLM הוא שכבת מיתון בלבד. הרשאות מינימליות, בידוד ואימות פלט נשארים יסודות, כי לתוקף מספיקה הצלחה אחת."],"category":"אימות ואבטחה","coverage":"כל התמליל הזמין נסקר. בטקסט שסופק מופיעים גוף ההרצאה, הסיכום ושאלות מהקהל. אין כאן אימות מול הווידאו או הוכחה שלא חסרו קטעים באמצע. מהירות תיקון ונתוני חולשות הם דיווחי הדובר, ללא אימות עצמאי כאן. קישורים לכלי אבטחה מתוך ההרצאה לא נבדקו בנפרד.","source_basis":"תמלול מלא שסופק (קובץ מקור 4, פריט 3), כולל שאלות ותשובות והודעת סיום של המנחה. תמלול אוטומטי עם שגיאות (שמות כלים משובשים, למשל 'Afterpay' ו'sneak').","lead":"AI יכול לצמצם את הפער בין אבטחה למפתחים, אם משתמשים בו כשכבת היגיון עם אדם בלולאה ולא כרשת ביטחון יחידה","chapters":[{"title":"הפער: מומחה אבטחה אחד לכל 100 מפתחים","body":["GitHub Security Lab הוא צוות מומחי אבטחה שמטרתו לאבטח קוד פתוח: מחקר (דוגמאות: Ruby SAML, וחולשת heap overflow ב-7-Zip שפורסמה בשבוע שעבר), וחינוך. לדבריו מצאו ותיקנו יותר מ-1,000 חולשות, ו-900+ קיבלו CVE.","הנתון המרכזי של הדובר: יש מומחה אבטחת יישומים אחד לכל 100 מפתחים. AI יכול לצמצם את הפער, אבל בלי ידע נכון הפער עלול לגדול. מטרת ההרצאה: להראות יתרונות וחסרונות כדי לשלב אדם בלולאה."],"points":[],"kind":"idea"},{"title":"בטיחות מההתחלה, והחסרונות של AI","body":["הוא מדבר נגד 'shift left' שבו תמיד נשאר פער בצד שמאל, ומציע 'start left'. הוא מראה דוגמאות מתחילת גל ה-AI: קוד עם SQL injection בשורה 23 (משתנה בשליטת המשתמש בשורה 22). גרסה מוקדמת של Copilot נשאלה מה לא בסדר, ומתוך שלוש תשובות אחת הייתה הזיה (סיסמאות בטקסט גלוי שלא קיימות).","שנית, אי-דטרמיניזם: על בסיס קוד עם עשר חולשות קיבל שמונה תוצאות. 'זה לא 80% דיוק': חולשת prototype pollution לא עלתה, וכשצמצם הקשר לקובץ הרלוונטי היא לא עלתה בכלל. החלפת מודל לא עזרה, ולכן 'זה לא רק המודלים, זה ה-scaffolding'. הוא מדגיש: בעולם האבטחה אין בעיית גילוי אלא בעיית תיקון, ולכן משתמשים בכלי אחר לגילוי ו-AI כשכבת הנימוק והתיקון.","המסר: AI לא מחליף אדם בלולאה ולא מדלג על בדיקות אבטחה. אל תהפכו אותו לרשת הביטחון היחידה."],"points":[],"kind":"idea"},{"title":"MCP ו-Skills כמבנה","body":["הוא מניח היגיינה בסיסית: להתקין שרתי MCP רק מכלים מהימנים ובהיקף הרשאה מצומצם. כלי AI לגילוי אינם דטרמיניסטיים ועלותם משתנה, אך מצטיינים בבעיות מערכתיות והקשריות (האם אני משתמש בפרימיטיבים קריפטוגרפיים נכונים? האם יש מידע רגיש בצד לקוח?) שכלים סטטיים כמו CodeQL לא מכסים. כלים סטטיים בוחנים תבניות; בעיות היום קשורות להתנהגות: קוד נכון תחבירית יכול לדלוף בגלל התנהגות שגויה. לכלים סטטיים עלות קבועה, ביטחון גבוה ובשלות.","כדוגמה: שרת GitHub MCP עם פונקציות code security, secret protection ו-security advisories מביא ממצאי צד שרת ל-CLI או ל-IDE כך שהסוכן מנמק עם הקשר. תרשים: MCP בלי Skills נותן יכולת בלי תהליך; Skills בלי MCP נותנים תהליך בלי כוח. Skills ניתנים לביקורת, תחזוקה והרחבה ב-registry."],"points":[],"kind":"idea"},{"title":"תיקון ב-PR וזרימות Agentic","body":["לפני AI: לוח בקרה של CodeQL עם רשימת בעיות וחומרה, והסברים גנריים. היום: Copilot Autofix מציע בתוך ה-PR הסבר והצעת קוד מבוססי הממצאים הדטרמיניסטיים, ואפשר להמשיך לערוך ולבצע commit שם. לדבריו מפתחים צריכים לעבוד במקום אחד, ה-PR, כי כל מעבר לאתר אחר יוצר חיכוך. כך, לטענתו, הלקוחות הפכו פי שלושה מהירים בתיקון, ו-GitHub תיקנה 600 חולשות בשבועיים (דברי הדובר).","Agentic Workflows: אם יש כלים סטטיים, למה סוכן? בגלל התאמה אישית (tailoring): הוא הגדיר סוכן אבטחה עם מה מחוץ להיקף, מה חשוב ואיך החברה עובדת, והסוכן מאתר חולשות ברמת הקוד, פותח issues או מתקן באותו מקום. הוא מזהיר שאם דוחסים הכול לסקריפט אחד, ההקשר מתנפח, ולכן חלק עובר לסוכנים, חלק לקבצים וחלק לכלים. הזרימות רצות לפי לוח זמנים או טריגר, באותם מכונות של GitHub Actions, ויש ספרייה חופשית (למשל סקירה אוטומטית וטריאז' של issues)."],"points":[],"kind":"idea"},{"title":"Taskflows, שרשרת אספקה ו-fuzzing","body":["Taskflows: צוותו, שיש לו גישה ל-Claude Mythos ולמודלים אחרים, פתח את הידע. 'המודלים לא מוצאים חולשות לבד; חוקרי אבטחה מכוונים אותם ומקודדים ידע לתוך taskflows'. אפשר לפתוח את המאגר ב-Codespace ולהריץ סקירות אבטחה ידניות בצורה אוטומטית (gh.io/taskflows, חינם וקוד פתוח).","שרשרת אספקה: רוב המפתחים מבלים יותר משלוש דקות, אצל חלקם מעל 30, בהחלטה אם להוסיף תלות. הם ארזו קובצי הוראות שמפיקים סיכום מנהלים עם סימוני אמוג'י ומקורות מהימנים (gh.io/risk). בהדגמה שאל 'ממה להיזהר בפרויקט Bootstrap?' והתשובות היו עקביות בין מודלים, כמו מומחה אבטחה.","Fuzzing: קשה לבני אדם לייצר מיליוני קלטים, ו-AI מייצר קלטים, boilerplate ו-harness ומאפשר לתקוף קוד בצורה בטוחה. גם בלי דטרמיניזם עדיין מוצאים ממצאים."],"points":[],"kind":"idea"},{"title":"מגרש משחקים לאבטחת סוכנים","body":["הוא בנה סביבה חינמית ב-Codespaces (דקות להתחלה) עם בוט בסגנון CLI, 'אינטרנט מדומה', סוכן שמחפש מידע של בורסה מדומה, ואתגרי שפה טבעית שבהם מנסים לגרום לצ'אטבוט לדלוף סודות. 'זה לא 2025: הוראות כמו התעלם מהקודמות לא יעבדו'. לדבריו הוא כבר שימש יותר מ-10,000 שחקנים, כולל ארגונים. המודלים האמיתיים מאחורי הקלעים הם של OpenAI, בחינם דרך חשבון GitHub."],"points":[],"kind":"idea"},{"title":"הזיות ותוצאות חיוביות שגויות מבזבזות זמן לצוותי פיתוח, אז איך מונעים את זה?","body":"אפשר להשתמש במספר מודלים (ממוצע) או להריץ כמה פעמים ולקחת את החיתוך, אבל העלות עולה. בטווח הארוך מומלץ להסתמך על חברות (GitHub, Semgrep, Snyk וכו') שמשלבות סטטי עם AI. הוא מדגיש חינוך: הדרכות וידאו לא עובדות; הוא מעדיף אימון מעשי. ואם היה CISO, היה קובע יעדי SLO לכל ספרינט עם 'קצבה' של בעיות פתוחות לפי חומרה.","kind":"qa"},{"title":"האם משתמשים ב-LLM כשופט?","body":"כן (כולל 'judge או jury'), גם ב-Azure. זו הקלה אך לא מושלמת: עקפו אותו בטענות כמו 'אני לא אדמין' ו'אני בודק'. תוקף צריך להצליח פעם אחת. לכן צריך גם סינון פלט, הרשאות מינימליות (AI לא נוגע בדבר רגיש), קונטיינרים, ולא להסתמך רק על שופט.","kind":"qa"},{"title":"מה נשאר מהסשן","body":[],"points":["AI מצמצם פער רק עם אדם בלולאה והיגיינת אבטחה.","הבעיה היא תיקון, לא גילוי; לכן PR הוא המקום לתיקון.","הקשר ותיאום (MCP, Skills, workflow) חשובים יותר ממודל מסוים."],"kind":"idea"}],"diagram":{"kind":"stack","title":"שכבות: מגילוי לתיקון עם אדם בלולאה","nodes":[{"id":"d","label":"גילוי: כלים סטטיים (CodeQL) + AI להקשר והתנהגות"},{"id":"m","label":"MCP: ממצאי שרת (code security, secrets, advisories)"},{"id":"s","label":"Skills: תהליך (טריאז', תיקון)"},{"id":"a","label":"סוכן: PR עם תיקון / issue / workflow"},{"id":"h","label":"אדם: סקירה, יעד SLO בספרינט"}],"edges":[{"from":"d","to":"m","label":""},{"from":"m","to":"s","label":""},{"from":"s","to":"a","label":""},{"from":"a","to":"h","label":""}],"caption":"התרשים בונה על הסדר שבו הדובר הציג שכבות; לא שקף ממוספר."},"terms":[{"term":"Shift left / Start left","definition":"להקדים את האבטחה לשלבי הפיתוח; הדובר מעדיף להתחיל משם בכלל."},{"term":"Copilot Autofix","definition":"הצעת תיקון חולשה בתוך ה-PR על בסיס ממצאי סריקה."},{"term":"Taskflows","definition":"זרימות שמקודדות ידע של חוקרי אבטחה כדי שמודל יריץ סקירה מכוונת."},{"term":"LLM as judge / jury","definition":"מודל שני שבודק את התוצר של הראשון, מקור סיכון שכן ניתן לעקוף."}],"gaps":["שם תוסף שהוזכר ('Afterpay' בתמלול) כנראה משובש; לא נקבע מה היה.","שקפים, ההדגמות והקוד אינם בתמלול; רק מה שנאמר.","בסוף ההרצאה המנחה מכריזה על המרת כל הרצאה ל-Skill, אך התמלול אינו מכיל פרטים על כך.","נתוני 1,000+ חולשות, 900+ CVE, 600 תיקונים בשבועיים, פי שלושה מהר יותר ו-10,000+ שחקנים הם של הדובר, ו-GitHub הוא מעסיקו.","הטענה על גישה ל-Claude Mythos היא של הדובר."],"source_refs":["https://www.youtube.com/watch?v=gc5_ICZg9tg"]}]);
